-- 内容增补 2026-10-26；先备份数据库。应用停止时执行，本补丁不在启动时自动重放。
-- 仅匹配本轮前的完整原值；已被后台改写的条目跳过。新攻略保留101至110编号。
PRAGMA foreign_keys=ON;
BEGIN IMMEDIATE;
UPDATE cities SET description='杭州的旅行可以从湖岸向外展开：西湖看水面、堤桥和山城关系，灵隐一带看山林中的寺院与院落。两种体验的步行强度、抵达方式不同，先选一段认真看，再决定是否组合，比一天赶完所有地点更有余地。',food='片儿川适合安排成一顿坐下来的正餐，葱包桧更适合作为街巷步行中的少量加餐。先确认份量、浇头和酱料，再决定是否加点；用餐地点顺着当天路线选，无须为了尝小吃往返不同湖岸。两人同行可分开选择主食与小吃，给下一餐留一点余地。',travel_advice='订住处时比较“到达车站—住处—当天起点”三段位置，而不只看是否写着西湖附近。湖边步行、公交换乘与前往灵隐的交通分别查询；返程选容易定位的入口或站点。旅行日最后一段先留给取行李和进站，避免用全部余量去追加景点。',visit_advice='第一次来，建议把两天拆成“湖岸一天、山林半天加机动半天”。湖岸选定起点与返程点，中间穿插坐下休息；灵隐参观单独核对入园安排，不把湖面上的直线距离当作转场时间。只有半天就留在一个片区，轻雨时缩短户外步行，大雨时优先改期。',revision=revision+1 WHERE id=1 AND NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1') AND description='湖岸、堤桥与城市街巷相连，适合留出步行与停留的时间。' AND food='片儿川、葱包桧等小吃可以作为认识杭州食味的入口。建议将用餐放在游览间隙，先看明码标价，再按自己的口味点餐。' AND travel_advice='建议将湖岸步行与其他片区分开安排；出发前查询公共交通路线，给步行、换乘和临时停留留出余量。' AND visit_advice='第一次来可先安排 1～2 天：一天留给湖岸，另一天从寺院或街巷中选一个主题。不必把所有地方塞进同一天。';
UPDATE cities SET description='成都可以用街巷与公园串起一段城市假期：宽窄巷子看院落与街道，锦里看仿古街区和民俗表达，人民公园则把休息、喝茶与观察日常放在一起。选一处作为半天的重点，再把用餐和转场放在中间，旅程会更完整。',food='钟水饺、担担面可以分到不同餐次，不必一顿尝完。点红油类小吃时具体说明辣油、蒜和调味是否分放，不能只用“少辣”代替沟通。先问份量，再决定是加餐还是正餐；同行有人口味清淡时，可以各自选主食，再共享少量适合分食的小吃。',travel_advice='先标出公园、两处街区与住处，逐段查询地铁、公交及步行接驳；不要因为都在城区就默认步行相连。街区结束后，约定清晰的集合点再离开人群。雨天可缩短露天步行，调整为已经核实开放的室内参观或一顿完整的用餐，保留返程余量。',visit_advice='两天玩法可分成“公园与宽窄巷子”和“锦里及周边文化参观”两条线，各留半天弹性。宽窄巷子与锦里不必连续赶场：一处偏院落观察，一处适合结合周边文化安排。只有一天时选两项重点即可，把茶座当作正式停留，而不是赶路之间随便坐一下。',revision=revision+1 WHERE id=2 AND NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1') AND description='从院落建筑看见城市记忆，也给茶馆与街头小店留一点时间。' AND food='钟水饺等成都小吃可作为街巷散步间的用餐选择。点餐时主动说明能接受的辣度，先少量尝试，再决定是否加点。' AND travel_advice='建议围绕一个片区步行游览，再查询公交或轨道交通前往下一片区。街巷游览尽量轻装，保留休息时间。' AND visit_advice='可先安排 1～2 天，以街巷与公园为主，每半天挑一个重点。想慢下来时，减少打卡数量，比赶路更合适。';
UPDATE cities SET description='南阳适合把人文参观做得细一点：卧龙岗的院落和碑刻提供空间线索，汉画馆的画像石让图像成为阅读历史的入口，医圣祠则转向人物纪念与地方文化。几个场所不必同日看完，先挑最感兴趣的一处，再安排另一种观看方式。',food='牛肉汤可与参观前后的正餐结合，先询问配饼、肉量与加料是否单独计费，再按饭量选择。新野板面属于另一条地方食味线索，新野县与南阳市区景点不是同一个步行片区；市区能否找到合适店铺应查具体位置，不为菜名临时增加一趟跨县往返。',travel_advice='武侯祠与汉画馆可作为同一片区考虑，但入口、开放与预约分别核对；到医圣祠另查完整去返路线。出发前保存正式场所名称，避免把名称相近的纪念地混淆。准备深度参观时给展签、讲解和休息留时间，最后一处结束后再安排用餐或返回，不用走马观花补足数量。',visit_advice='一天可围绕卧龙岗和汉画馆组织，上午看建筑与碑刻，午后选画像石主题细读；实际顺序仍以各场所当天开放安排为准。两天则把医圣祠放到另一段，增加人物文化的阅读。带长辈或孩子时，每处只设一个问题，例如“这幅车马图在讲什么”，比连续背诵人物年表更容易投入。',revision=revision+1 WHERE id=3 AND NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1') AND description='从武侯祠的院落与碑刻出发，认识城市的历史文化。' AND food='南阳牛肉汤、新野板面是了解地方食味的线索。可以选其中一种作为一餐；新野属于南阳所辖县，寻找具体店铺时请核对位置，不要仅凭菜名判断距离。' AND travel_advice='人文场馆之间建议逐段查询路线，不把地图上的直线距离当作实际步行距离。遇到预约或开放调整，以场馆公告为准。' AND visit_advice='建议留出 1～2 天慢读人文内容。武侯祠、汉画馆和医圣祠可按兴趣选择，想细看展陈时，给每处留足停留时间。';
UPDATE cities SET description='泉州的看点有不同尺度：开元寺与西街适合近距离看塔、建筑和街巷，洛阳桥则把视线转向河口与石桥。可以先在古城读懂一小片空间，再给古桥留出单独的交通和观察时间；用一碗面线糊或一份肉粽，串起旅行中的休息。',food='面线糊与烧肉粽适合分开品尝：前者先选基础份再确认加料，后者先问大小和馅料。面线糊的不同配料可能分别计价，肉粽的蘸酱也可先少量尝试。安排小吃时留一段坐着吃的时间，不一边穿过拥挤街巷一边端热汤；完整一餐后再决定是否继续加餐。',travel_advice='把古城住处、开元寺入口与洛阳桥实际位置同时放上地图，先看转场是否顺路。古城短距离适合按体力步行，前往古桥则另查交通，不能按两个地名之间的直线估时。遇到街巷人流集中时，提前约定易识别的集合点，结束游览后再从方便接驳的位置返程。',visit_advice='古城半日可围绕开元寺和西街，先看寺院整体，再选一段街巷，不追逐全部机位。第二天或另一个半天再考虑洛阳桥，提前确认往返交通；若只有一天，宁可保留古城的完整步行，也不要压缩古桥到只剩下车拍照。雨天先减少桥面和石板路停留，再按开放情况调整。',revision=revision+1 WHERE id=4 AND NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1') AND description='寺院、石塔与老街相互连接，适合以步行为主的城市探索。' AND food='面线糊是认识泉州小吃的一个入口。可以从一份简单搭配开始，再根据口味选择配料；购买前问清份量和价格。' AND travel_advice='建议把古城步行和城外景点分开安排。跨片区出行前查询实际交通时间，给步行、候车与休息留出余量。' AND visit_advice='先安排 1～2 天，以古城人文为主，再按时间选择桥梁或其他地点。古建阅读适合慢看，避免仅为拍照频繁折返。';
UPDATE cities SET description='大理适合按片区慢慢展开：古城看街巷与日常，崇圣寺三塔看建筑组合和历史线索，洱海则选择一段明确的湖岸停留。古城、大理站和湖岸目的地不能混为一个位置，先把住处与交通关系理清，再决定每天的重点。',food='乳扇可以少量尝试，点单时确认做法、酱料与份量；不喜欢奶香或甜味的人可以与同伴分食。巍山耙肉饵丝属于大理州另一片区的风味，巍山县不等于大理古城附近。已有古城与湖岸计划时，先找顺路的餐食，不要只为一种小吃临时加一趟跨片区赶路。',travel_advice='订交通前先区分大理站、下关城区、古城与湖岸的具体位置。选定湖岸去处时同步查返程，不把“洱海”当作一个固定下车点；同日组合三塔与古城也应查询实际接驳。带行李换住宿会占据时间，尽量把移动放在一天的开头或结尾，避免来回折返取物。',visit_advice='两天可安排“古城加三塔”和“一段湖岸”两种主题，实际先后顺序随天气调整。三天时增加半天抵达与休息余量，不必把多出来的时间全部变成环湖点位。湖岸只选一个明确片区，古城只选几条街细走，比较适合希望拍照、阅读和吃饭都不赶的人。',revision=revision+1 WHERE id=5 AND NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1') AND description='把古城街巷和湖岸风景分开安排，给沿途的停留留出余地。' AND food='乳扇是大理地方特产之一。作为用餐间的小食适量尝试即可，乳制品过敏者请先确认配料；购买前看清标价。' AND travel_advice='建议将古城、湖岸与其他片区分开查询交通，不把环湖当作一次短距离步行。自驾、骑行或公共交通按实际路线和体力选择。' AND visit_advice='可先留出 2～3 天：古城一天、湖岸一天，再按兴趣选择其他人文地点。每天安排少一点，给天气和休息留有空间。';
UPDATE spots SET description='西湖不只是一片湖水。湖泊、周边山丘与历代增建的堤、桥、岛、园林共同形成文化景观，观看时既能看远处山城关系，也能近看树木、桥栏与水面的层次。
可以选一段湖岸完成“远看—近看—回望”的小循环：先看开阔水面，再留意堤桥怎样连接空间，走过一段后回头比较视线。建议留出2～3小时慢走与休息，不以走完一整圈作为完成标准。',highlights='看湖面、山丘和城市怎样进入同一幅视野；比较堤岸两侧水面与树影；在不同距离观察桥与岛的关系，试着把喜欢的一处写成一句话。',transportation='起点和终点同时确定，再查实际交通。湖岸路段之间不一定都适合连续长距离步行；途中若追加游船，须另算候船、上下船和返回时间。',tips='阴雨也能观察倒影与近景，但雨大时缩短临水步行，遇到风雨按现场管理调整。拍照停在不阻碍通行的位置；收费项目与入园安排单独核对。',revision=revision+1 WHERE id=1 AND NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1') AND description='西湖文化景观由湖泊与周边山丘、堤岸、岛屿和园林共同构成。这里适合以一段湖岸为起点，观察不同距离下的水面和城市。' AND highlights='先选一段湖岸慢走；留意堤桥和树木构成的视线变化；用步行感受城市与湖面的联系。' AND transportation='先确定当天的起点和终点，再查询实时公共交通。湖岸范围较大，行程不宜全部依靠步行。' AND tips='夏季注意防晒和补水，雨天留意湿滑路面。游船与其他收费项目请查看官方公告。';
UPDATE spots SET description='宽巷子、窄巷子与井巷子以及其间的院落，组成了宽窄巷子的空间骨架。它既有历史街区的格局，也包含当代商业与修缮后的使用方式，适合把“街道如何连接院落”作为参观主题。
先在一条巷子观察门头和入口，再换到另一条比较街宽、铺面与人的停留位置。建议留出1～2小时，选两三个真正感兴趣的地方看细节，消费和进入院落都按店铺现场规则决定。',highlights='比较三条巷子的尺度；看门头、砖墙与院落入口怎样组织视线；区分可自由通行的街巷与需要消费或预约的内部空间。',transportation='先确定街区入口与离开位置，再查询公共交通及最后一段步行。与人民公园组合时也需逐段导航；不要把宽窄巷子与锦里视为同一条街。',tips='早晚氛围会随人流和营业情况变化，不承诺固定的“无人时段”。试吃、体验与拍摄前先问是否收费；住宅、店内和人物拍摄尊重对方意愿。',revision=revision+1 WHERE id=2 AND NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1') AND description='宽窄巷子由三条平行的老式街道及院落群组成，是认识成都街巷空间的一处入口。逛街之外，也可以留意门头、墙面和院落的细节。' AND highlights='比较不同巷子的空间尺度；观察院落入口；留出一段可以随意走走的时间。' AND transportation='出发前查询地铁与步行导航。街区内部适合步行，离开前先确认返回住处的方式。' AND tips='商铺营业安排各不相同。拍摄店铺与行人时留意他人意愿，消费前确认价格。';
UPDATE spots SET description='锦里是紧邻成都武侯祠东侧的仿古街区，以川西民居的建筑意象和民俗、休闲内容组织空间。它适合看当代街区怎样展示地方文化，也适合放在正式文化参观之后，作为一段放松的步行。
可先顺着导览走一段，观察转角、匾额与铺面，再选自己愿意停留的一处。计划武侯祠博物馆参观时，需要另留完整时间；街区散步不等于完成博物馆游览。',highlights='观察转角与街道视线；看建筑立面、匾额与商业使用之间的关系；把民俗体验与建筑观看分开选择，避免一路只顾寻找同款照片。',transportation='导航时确认是锦里街区还是武侯祠博物馆入口。若两者同日参观，分别核对入园要求，再留出中途用餐和休息；返回住处不以走到街区出口为结束。',tips='体验、餐饮与购物各自计费，先看价格再决定。街巷人多时在开阔位置集合，避免停在狭窄转角；不因一段仿古街景就把整条街当作原状保存的古代建筑。',revision=revision+1 WHERE id=3 AND NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1') AND description='锦里位于成都武侯祠东侧，是结合建筑、民俗和休闲体验的街区。可以与周边文化场所分段安排，避免匆忙地只拍照打卡。' AND highlights='观察建筑立面与匾额；选择一段步行游览；把街区体验和文化参观分开留时间。' AND transportation='先在导航中确认目的地入口，参观武侯祠的安排请另外查阅博物馆官方信息。' AND tips='街区与博物馆参观不是同一项安排。餐饮和体验项目以现场明码标价为准。';
UPDATE spots SET description='南阳武侯祠位于卧龙岗，是从建筑、碑刻与人物纪念理解地方文化的一处入口。这里适合用院落的推进关系来组织参观：先看空间怎样变化，再选几块碑刻或一处建筑细部慢读。
参观不必从背诵人物年表开始。可带着“哪段文字、哪处空间最让我停下”这个问题，记录现场说明，再查阅可靠资料补充理解。建议按个人阅读习惯留出2小时左右，深看时另增余量。',highlights='沿现场导览看院落的层次；选择一处碑刻读落款与说明；把人物纪念、建筑用途和后世修建留下的痕迹分别理解。',transportation='使用完整名称“南阳武侯祠”并确认官方入口，避免与成都同名场所混淆。若继续汉画馆，分别查开放和入馆安排，再计算出口到下一入口的路程。',tips='历史叙述以现场展签及可靠资料相互印证，不将文学情节直接当作遗址证据。碑刻与古建不触摸、攀靠或拓印；讲解与入园服务以景区公告为准。',revision=revision+1 WHERE id=4 AND NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1') AND description='南阳武侯祠位于卧龙岗。参观时可以从建筑与碑刻入手，再结合现场说明了解相关文化。不同院落之间值得放慢脚步，仔细阅读展陈。' AND highlights='沿院落顺序参观；留意碑刻和建筑细部；结合现场展陈理解人物与地方历史。' AND transportation='按景区公布的入口规划出行，公交和其他交通方式请在出发当天查询。' AND tips='参观前查阅景区公告，涉及讲解和展陈开放的安排以官方信息为准。古建空间内遵守参观规则。';
UPDATE spots SET description='开元寺位于泉州西街，镇国塔和仁寿塔是认识寺院的重要线索。除了远处同时看见两塔，也可以在允许到达的位置观察石构建筑如何表现檐、柱与层次，再回到寺院轴线理解整体空间。
建议先浏览导览，再挑双塔、殿宇与石刻中的一两项细看。约1.5～2小时的从容参观更利于阅读细部；与西街步行组合时，把离寺后的街巷和用餐另留一段。',highlights='从不同站位比较双塔；在允许范围观察石塔的仿木构细节；先看建筑轴线，再读说明，留意不同年代留下的内容。',transportation='确认入口与当日开放要求，再安排古城步行。洛阳桥需要另外查询往返交通，不把它排成西街步行中的“顺便一站”。',tips='寺院仍有宗教活动，保持安静并服从现场引导。摄影只在允许区域进行，不为拍全景越过围栏；雨后留意石板路与台阶。',revision=revision+1 WHERE id=5 AND NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1') AND description='开元寺位于泉州西街，寺院内保存有镇国、仁寿两座石塔。参观可以先看整体空间，再停下来观察建筑和石刻的细节。' AND highlights='从不同方向观察双塔；认识寺院的空间布局；结合说明牌阅读建筑与石刻。' AND transportation='目的地位于泉州古城街区，建议把周边步行与寺院参观分开规划，出发前确认开放安排。' AND tips='保持安静，遵守寺院参观要求。未经允许不进入限制区域，相关仪式与拍摄要求以现场指引为准。';
UPDATE spots SET description='洱海是大理重要的湖泊景观，但“去洱海”还不是一个具体行程：不同湖岸片区相隔的距离、接驳方式与允许活动范围有差别。选一个明确的到达点和返程点，才容易把风景与日常步行放进半天。
可以给一段开放湖岸留2～3小时，先看远处山体与湖面的关系，再观察近处风、树影与岸边空间。湖岸停留不等于环湖，临时看到漂亮照片也不必马上追加另一侧的目的地。',highlights='同一地点停留后再比较湖面变化；看山体和湖岸形成的远近层次；把拍照、休息与观察分成几段，给返程保留完整时间。',transportation='地图中输入具体湖岸地点，查询实际去程与回程。若选择骑行，另查允许路段、车辆归还与体力要求，不能把任意湖岸道路都视为骑行线路。',tips='选择开放步道，不进入水中、湿地或限制区域取景。按当天风雨及时缩短行程，防晒与衣物准备按实际天气；不要依赖一场必须出现的日落完成计划。',revision=revision+1 WHERE id=6 AND NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1') AND description='洱海是大理重要的自然景观。湖岸不同片区的距离和交通条件有区别，选择一个适合自己的片区，比匆忙追赶多个地点更容易留下感受。' AND highlights='观察湖面与远处山体；选择适合步行的开放路段；把停留时间计入行程。' AND transportation='先确认具体的湖岸目的地和交通方式，再安排去程与返程。不要把整个湖岸当作一个很近的地点。' AND tips='留意风、紫外线和天气变化，选择允许通行的区域。相关交通与活动信息以现场公告为准。';
UPDATE spots SET description='大理古城适合以街道、院落与沿街生活作为观察对象。比起一次走遍全部店铺，更容易实行的方法是：选两三条街构成一段闭合步行，记住入口、休息点与回程方向，让逛街有清晰的起止。
建议留一个半天，先熟悉街道，再按兴趣看建筑或小店。与三塔组合时先解决接驳，与湖岸组合时则更适合另留半天，不把古城仅当作其他景点之间的取餐与换乘位置。',highlights='看街道怎样连接院落与铺面；主街之外选择允许通行的街巷；从一个转角回看空间，记录自己喜欢的细节，而不是只收集店名。',transportation='先区分古城、下关城区和大理站，再确认住处与下车位置。拖行李进街巷前了解抵达方式，出城返回车站时给接驳与进站分别留余量。',tips='店铺、住宿与私人院落各有使用边界，拍摄或进入前先询问。路面有高差时放慢脚步，夜间步行仍保持对方向与返程的判断；购物先确认规格和价格。',revision=revision+1 WHERE id=7 AND NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1') AND description='大理古城是大理的历史文化街区之一。浏览主街之外，也可以安排一段安静的街巷步行，通过建筑与日常生活认识地方。' AND highlights='先熟悉街道方向；观察建筑与院落；按自己的节奏选择停留点。' AND transportation='抵达前确认车站、住处与古城之间的位置关系，按实时交通信息选择合适方式。' AND tips='古城游览与湖岸出行可以分段安排。提前了解天气，步行时穿着舒适鞋履。';
UPDATE spots SET description='灵隐寺位于西湖以西的山林环境中，寺院建筑与周围峰峦共同构成了与湖岸不同的观看体验。参观时可从一组殿宇与院落入手，先看前后空间，再读匾额和说明，把山林、建筑与安静行走联系起来。
建议留2～3小时作为编辑参考，不包含抵达、候入和周边其他区域。灵隐寺、附近景区与登山路线各有安排，不能仅凭一个地名就认为一次入园可以完成所有内容。',highlights='按导览观察殿宇前后的空间；比较山林遮挡与建筑显露的关系；选择一处建筑细节阅读，不将祈愿、购物与参观混为必做清单。',transportation='先核对具体参观区域、预约与入园信息，再查询实时交通。若与西湖同日组合，给换乘与中途用餐留出单独时段；走完湖岸后不要直接按剩余地图距离追加山路。',tips='尊重宗教活动，拍摄前看标识，禁止进入的区域不探看。湿滑台阶缓行；带长辈同行先评估步行与高差，再决定是否加入周边路线。',revision=revision+1 WHERE id=21 AND NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1') AND description='灵隐寺位于杭州西湖以西，是杭州历史悠久的寺院。可以把参观重点放在建筑空间与山林环境，沿现场导览逐段认识。' AND highlights='观察殿宇与院落的空间关系；留意匾额与建筑细部；在允许参观的范围内安静行走。' AND transportation='先在官方渠道确认入园和预约安排，再规划抵达方式。附近不同参观区域的安排需要分别核对。' AND tips='寺院内尊重宗教活动和现场要求，拍照前留意标识。遇到台阶、雨天路面时放慢脚步。';
UPDATE spots SET description='人民公园适合认识成都的城市休闲：沿步道走一段，再选一处坐下来，观察喝茶、交谈与日常活动如何使用公共空间。旅行也可以在这里暂停移动，用一段停留理解城市，而不必马上寻找下一个景点。
建议留1～2小时；如果想坐茶座，就把它算作正式活动，减少之后的街区数量。公园散步和各经营项目的消费分开考虑，是否参与体验由个人兴趣决定。',highlights='先走一小段再选择停留；观察茶座与步道不同的节奏；把声音、树影和人与空间的关系记下来，避免只拍一张环境照片就离开。',transportation='先查住处到公园入口的接驳，再安排结束后的用餐或下一片区。与宽窄巷子组合可按地图逐段核对，不因同属城区就忽略转场时间。',tips='茶座和体验项目先询问消费方式、份量与计价。活动中的市民不是固定表演，拍人像先征得同意；新闻中的节庆活动不代表每天都有相同安排。',revision=revision+1 WHERE id=22 AND NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1') AND description='成都人民公园是认识城市休闲生活的一处空间。园内的湖面、步道与茶社让旅行不必一直赶路，可以选一段适合自己的慢行。' AND highlights='在湖岸观察城市日常；按兴趣选择茶社停留；把休息本身也作为旅行的一部分。' AND transportation='把公园与当天的住处、用餐点放到地图上考虑，先查实时交通。选择一个方便返程的位置结束步行。' AND tips='公园里的体验和消费项目各自经营，点单前确认价格。拍摄活动中的市民前先征得同意。';
UPDATE spots SET description='南阳市汉画馆以汉画像石的收藏、展示与研究为特色，位于卧龙岗南端。画像石中的人物、车马、动物与纹样，可以成为认识古代生活和观念的线索；参观时不必逐块背下名称，更适合挑一个图像主题比较。
可先看导览和展陈说明，再选三件作品：一件看画面整体，一件看动作与线条，一件读展签后回看。建议留1.5～2小时，阅读较多或跟随讲解时增加余量。',highlights='用人物、车马或纹样作一条主题线；比较不同画面的构图与动作；区分画面直接可见的内容和展签提供的解释，参观后再查资料。',transportation='核对正式馆名、入口与当天开放安排。与武侯祠同日安排时，分别确认参观条件，不把两处当作同一入口或一张票可以直接通行的场所。',tips='画像石纹样不触摸，不为拍清细节违反灯光和摄影规定。内容解读优先依据馆方展签；如果只剩少量时间，就选一个主题看完整，避免一路快速扫拍。',revision=revision+1 WHERE id=23 AND NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1') AND description='南阳市汉画馆是收藏、展示与研究汉画像石的专题博物馆，位于卧龙岗南端。参观时可以挑选几个感兴趣的画面，结合展签理解图像中的生活与观念。' AND highlights='先读展陈导览，再看画面细节；比较人物、车马与装饰纹样；选择自己感兴趣的主题慢慢看。' AND transportation='参观前核对博物馆公告，了解开放和预约要求。结合卧龙岗周边安排，预留入馆与阅读展签的时间。' AND tips='展厅内遵守拍摄和参观规定。开放、预约与临时展览情况以博物馆最新信息为准。';
UPDATE spots SET description='医圣祠是了解张仲景纪念文化的一处场所。参观可以从人物生平、纪念建筑与现场展陈三个层面展开，先看空间，再带着具体问题阅读说明，例如一段文字怎样介绍人物与地方的联系。
它与卧龙岗片区适合分段安排，建议按兴趣留1～2小时。本页面使用2005年历史资料照片，照片用于认识场所，不能据此推断今天入口、展陈或周边环境的样貌。',highlights='沿现场导览认识纪念空间；选择一段人物说明细读；比较建筑观看与展陈阅读各自带来的信息，把不确定的问题记下再查可靠资料。',transportation='导航前核对当前对外开放场所、正式入口与交通，避免根据旧照片找门。与武侯祠或汉画馆组合时另外计算转场和返程，不只按参观时长相加。',tips='人物文化介绍用于参观阅读，不作为诊疗或用药建议。开放、预约、讲解与拍摄以场所最新公告为准；历史照片与今天现场可能有差异。',revision=revision+1 WHERE id=24 AND NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1') AND description='医圣祠是纪念张仲景的文化场所。可以结合建筑、展陈和现场说明认识相关历史，避免只凭一张照片匆匆打卡。本页使用2005年资料照片，当前面貌请以官方信息为准。' AND highlights='了解纪念建筑与张仲景文化的联系；阅读展陈中的人物与著作介绍；留意庭院与建筑布局。' AND transportation='出发前确认医圣文化相关场所的当前入口、开放与预约安排，使用实时导航规划交通。' AND tips='资料照片用于认识历史建筑，不代表当前全部展陈或场地面貌。参观安排和开放区域以官方公告为准。';
UPDATE spots SET description='洛阳桥又称万安桥，横跨泉州洛阳江河口，是认识石桥结构与交通历史的一个入口。先从岸边允许到达的位置看桥如何跨越水面，再观察桥墩、桥面与石刻，可以把“如何通行”变成一个具体问题。
建议留1～1.5小时看整体和细部，另算去返交通。这里不是西街旁的一段短步行，也不因为名称含“洛阳”就位于河南；规划时使用泉州洛阳桥的完整定位。',highlights='先看桥与两岸的关系；在开放范围观察桥墩、桥面和附属石刻；结合官方说明理解建桥背景，不为看桥底自行下到危险位置。',transportation='提前查古城或住处到桥的实际交通，同步确认回程方式。桥两端与接驳位置可能不同，先约定结束在哪一侧，再组织后续路线。',tips='风雨时缩短桥面停留，石材表面湿滑要慢行。遵守文物与现场通行要求，不攀爬栏杆或到非开放岸线拍照；不把潮汐状态写成必定能看到的景观。',revision=revision+1 WHERE id=25 AND NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1') AND description='洛阳桥位于泉州洛阳江入海口，原名万安桥。它是认识泉州古代交通与桥梁技术的重要遗产，桥体和附属石刻都值得结合说明阅读。' AND highlights='观察石桥与桥墩；阅读与建桥相关的说明；从桥上与岸边不同角度看桥梁空间。' AND transportation='洛阳桥不在西街步行范围内，请单独查询往返交通。当天同时安排古城游览时，应把路程计入行程。' AND tips='桥面和岸边注意脚下，选择允许通行的路线。风雨天气按实际情况调整，文物保护区域遵守现场规定。';
UPDATE spots SET description='崇圣寺三塔位于大理古城西北侧。主塔千寻塔与后方两座小塔形成组合，塔身的平面、层次与比例各有特点，适合先看三塔整体，再在允许范围内比较单塔细节，联系南诏、大理国相关历史阅读。
建议留2～3小时作为参观参考；把园区内步行与其他参观区域算进去。这里的建筑观看与古城街巷、洱海湖岸是三种体验，不必为了同日全部出现而缩短每处停留。',highlights='从开放站位看三塔前后关系；比较主塔与小塔的平面和檐层；先读一块相关说明再回看建筑，理解整体组合而不只寻找倒影机位。',transportation='先确认具体入口和当日参观安排，再查与住处或古城的接驳。地图上的相邻不代表无需交通与步行时间；行程结束后给回城用餐和返回留余量。',tips='古塔、现有寺院空间和不同参观区域按现场说明理解，不把所有建筑视作同一年代原物。拍照遵守开放范围，长时间户外停留按天气准备，票务查官方渠道。',revision=revision+1 WHERE id=26 AND NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1') AND description='崇圣寺三塔位于大理古城西北，是大理具有代表性的历史建筑。主塔与两座小塔共同构成可以从多个角度观察的建筑组合。' AND highlights='先看三塔整体布局；在允许的位置观察塔身细节；结合展陈了解建筑与地方历史。' AND transportation='从住处或古城出发前，分别查询交通、门票和预约信息。景区参观留出步行和休息时间。' AND tips='不要攀爬或进入限制区域。山地天气与日照变化明显，按当天天气准备；开放与票务以景区公告为准。';
UPDATE guides SET sections='[{"title":"先确定一段湖岸","body":"先在地图上找到方便到达的起点，再选择一个便于返程的终点。行程中保留可以坐下来休息的空白，遇到喜欢的水面和树影时就停一会儿。"},{"title":"怎样安排节奏","body":"如果只有半天，可以把精力留给步行、观察和拍照。想乘船或进入收费场所时，提前查看该项目的官方信息，并给排队和返回留时间。"},{"title":"交通与用餐","body":"湖岸的不同位置与公共交通连接情况不一样，出发前查询当天路线。用餐可以安排在行程结束后，先确认餐厅位置和价格，再决定是否绕路。"},{"title":"出发前看一眼","body":"带好饮水，按天气准备遮阳或雨具。资料中的景观介绍用于认识目的地，开放与交通安排请以当天官方公告为准。"},{"title":"一个下午可以怎样拆分","body":"以下为弹性示例：先用20分钟熟悉起点与方向，接着留60～90分钟沿选定湖岸步行，遇到喜欢的地方停留，再留30分钟坐下休息或用餐，最后按实时交通返程。它不是固定线路表；若增加游船，应减少步行路段，而不是把候船与返回塞进原有空白。湖面、堤桥、树影选一个作为观察重点，半天也可以看得完整。"},{"title":"下雨或走累时怎么收尾","body":"轻雨时可以减少远距离移动，把注意力转向近处桥栏、屋檐与水面；雨势大时优先结束临水步行，不用为了完成路线继续前进。出发前记住一处方便定位的返回点，走累后直接向那里收尾。带孩子或长辈同行，宁可删掉最后一段，也不把返程时间当作可随意压缩的余量。"}]',revision=revision+1 WHERE id=1 AND NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1') AND sections='[{"title":"先确定一段湖岸","body":"先在地图上找到方便到达的起点，再选择一个便于返程的终点。行程中保留可以坐下来休息的空白，遇到喜欢的水面和树影时就停一会儿。"},{"title":"怎样安排节奏","body":"如果只有半天，可以把精力留给步行、观察和拍照。想乘船或进入收费场所时，提前查看该项目的官方信息，并给排队和返回留时间。"},{"title":"交通与用餐","body":"湖岸的不同位置与公共交通连接情况不一样，出发前查询当天路线。用餐可以安排在行程结束后，先确认餐厅位置和价格，再决定是否绕路。"},{"title":"出发前看一眼","body":"带好饮水，按天气准备遮阳或雨具。资料中的景观介绍用于认识目的地，开放与交通安排请以当天官方公告为准。"}]';
UPDATE guides SET sections='[{"title":"从三个巷子的差异看起","body":"到达后先熟悉周边街道，选择一条巷子慢走。观察门头、院落入口和街道宽度，找到自己感兴趣的细节后再继续。"},{"title":"留一点自由时间","body":"不必把每一间店铺都排进计划。可以选择一家自己喜欢的小店停留，也可以只在街边观察来往的人与建筑。涉及消费时先确认价格。"},{"title":"用餐与交通","body":"吃饭时间和街区游览可以分开安排。出发前查实时交通，离开时留足步行到车站的时间。热门时段的现场体验会有所不同。"},{"title":"随手记录","body":"拍下吸引你的建筑细节，记录自己的路线和感受。拍摄他人、店内陈设或开展体验前，先尊重现场要求。"},{"title":"用三个问题看院落","body":"第一次逛可给自己三个小问题：入口为什么设在这里，墙与门怎样引导视线，人在什么位置愿意停下来。每条巷子只选一个细节比较，拍照时留下一张整体与一张局部，回看更容易记住差别。开放的街巷与经营场所内部有不同边界，不为了完成观察而推门进入私人或限制空间。"},{"title":"公园与街巷怎样组合","body":"想增加人民公园时，先完成公园步行或茶座停留，再按交通与饭点转到宽窄巷子；两处之间的接驳另算，不默认全程顺路。想认真坐一会儿，就把街区缩成一段；想逛店，则减少茶座时间。雨天不把屋檐当作连续避雨路线，遇到拥挤也可以结束街区，用一顿坐下来的饭收尾。"}]',revision=revision+1 WHERE id=2 AND NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1') AND sections='[{"title":"从三个巷子的差异看起","body":"到达后先熟悉周边街道，选择一条巷子慢走。观察门头、院落入口和街道宽度，找到自己感兴趣的细节后再继续。"},{"title":"留一点自由时间","body":"不必把每一间店铺都排进计划。可以选择一家自己喜欢的小店停留，也可以只在街边观察来往的人与建筑。涉及消费时先确认价格。"},{"title":"用餐与交通","body":"吃饭时间和街区游览可以分开安排。出发前查实时交通，离开时留足步行到车站的时间。热门时段的现场体验会有所不同。"},{"title":"随手记录","body":"拍下吸引你的建筑细节，记录自己的路线和感受。拍摄他人、店内陈设或开展体验前，先尊重现场要求。"}]';
UPDATE guides SET sections='[{"title":"参观之前","body":"先查阅景区的开放和入园公告，确定入口与交通。想深入理解展陈时，可以提前了解官方讲解安排，而不只依赖网上的简略介绍。"},{"title":"把院落当作线索","body":"沿参观顺序留意建筑、碑刻与说明牌之间的联系。遇到陌生的人名或故事时先记下来，回去再查资料，比匆忙扫过每个角落更有收获。"},{"title":"给行程留白","body":"参观与周边城市散步可以分成两段。根据天气和体力安排休息，用餐选择靠近返程路线的地方即可，避免为了赶路打断参观。"},{"title":"阅读与尊重","body":"历史内容结合官方资料与现场展陈阅读。古建筑内遵守参观规则，拍照前留意提示，让后来的游客也能安静观看。"},{"title":"把参观变成一张阅读卡","body":"选一处院落，记录名称、看到的布局和一个尚未理解的问题；再选一块允许观看的碑刻，先读说明而不是急着识完每个字。把直接看到的内容与讲解中的解释分别记下，参观后再查人物和年代。这样的三五条记录足以支撑一次回顾，不需要拍遍所有碑刻，也不必把传说和文学叙述当作同一层面的证据。"},{"title":"与汉画馆衔接时怎样取舍","body":"若计划继续汉画馆，可用建筑与图像两种观看方式分配精力：武侯祠重点看空间，汉画馆重点挑一个画像主题。午间留出用餐和休息，两处的入馆条件分别确认。如果在第一处已经读得很投入，就减少第二处展品数量；时间不足时改到另一半天，不用快速穿过全部展厅来完成清单。"}]',revision=revision+1 WHERE id=3 AND NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1') AND sections='[{"title":"参观之前","body":"先查阅景区的开放和入园公告，确定入口与交通。想深入理解展陈时，可以提前了解官方讲解安排，而不只依赖网上的简略介绍。"},{"title":"把院落当作线索","body":"沿参观顺序留意建筑、碑刻与说明牌之间的联系。遇到陌生的人名或故事时先记下来，回去再查资料，比匆忙扫过每个角落更有收获。"},{"title":"给行程留白","body":"参观与周边城市散步可以分成两段。根据天气和体力安排休息，用餐选择靠近返程路线的地方即可，避免为了赶路打断参观。"},{"title":"阅读与尊重","body":"历史内容结合官方资料与现场展陈阅读。古建筑内遵守参观规则，拍照前留意提示，让后来的游客也能安静观看。"}]';
UPDATE guides SET sections='[{"title":"先认识寺院空间","body":"参观时先看整体布局，再停下来观察石塔与建筑。结合官方介绍和现场说明理解细节，保持安静，遵守参观要求。"},{"title":"街巷慢走","body":"离开寺院后再按体力安排周边步行。先确定一个方便返回的终点，留一点时间给巷口和沿街店铺，不必追赶所有热门拍照点。"},{"title":"尝一点当地味道","body":"旅行中的用餐也可以是一段休息。先看清菜单和价格，再按自己的喜好选择。不要为了吃遍清单而压缩参观和休息的时间。"},{"title":"出行小提示","body":"提前查询天气与交通，鞋子以适合步行为主。寺院的开放、拍摄和参观安排以官方公告与现场指引为准。"},{"title":"一段古城半日的顺序","body":"可把半天分成寺院参观、街巷步行、坐下用餐三段，先让开元寺占据完整时段，离寺后再决定西街走多远。面线糊与烧肉粽选择一种作为起点，另一种留到下次或与同伴分享。预计行程结束前先确认接驳方向，避免逛到最后才发现返回住处需要再次穿过拥挤街巷。"},{"title":"看双塔时不只找同款角度","body":"先从允许站立的位置观察双塔的整体关系，再分别留意塔身层次、石构细节与周边建筑。可以拍一张远景、一张局部，回看时写一句两张照片提供了什么不同信息。不需要为了让两座塔同时入镜进入限制区域；寺院的活动秩序与其他参观者的通行优先于构图。"}]',revision=revision+1 WHERE id=4 AND NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1') AND sections='[{"title":"先认识寺院空间","body":"参观时先看整体布局，再停下来观察石塔与建筑。结合官方介绍和现场说明理解细节，保持安静，遵守参观要求。"},{"title":"街巷慢走","body":"离开寺院后再按体力安排周边步行。先确定一个方便返回的终点，留一点时间给巷口和沿街店铺，不必追赶所有热门拍照点。"},{"title":"尝一点当地味道","body":"旅行中的用餐也可以是一段休息。先看清菜单和价格，再按自己的喜好选择。不要为了吃遍清单而压缩参观和休息的时间。"},{"title":"出行小提示","body":"提前查询天气与交通，鞋子以适合步行为主。寺院的开放、拍摄和参观安排以官方公告与现场指引为准。"}]';
UPDATE guides SET sections='[{"title":"先看距离再排计划","body":"先标出住处、古城和想去的湖岸位置，再确认交通方式。抵达与返程都需要时间，行程不宜只按照片中的感觉安排。"},{"title":"一段古城步行","body":"在古城里选择几条街道慢走，留意建筑和沿街日常。可以在自己喜欢的小店停留，也可以找一处地方休息，不必一直移动。"},{"title":"一段湖岸停留","body":"去湖岸前查天气并确认开放区域。在允许通行的路段活动，把风景、步行和休息放在同一段行程里，返程安排提前考虑。"},{"title":"出发准备","body":"注意防晒、风和天气变化。餐饮与交通花费可以按自己的实际安排记录，实时开放与交通信息请查询官方渠道。"},{"title":"两天安排的可调版本","body":"第一天把古城作为主要步行片区，有兴趣再结合三塔参观，给两者之间的接驳和午餐留出完整时段。第二天选一个明确的洱海湖岸去处，去返一起查，拍照和休息算在同一半天里。若第一天抵达较晚，就只保留古城的一小段，不把三塔和湖岸连夜补齐；有第三天时，把它留作天气与返程的弹性。"},{"title":"为什么不把环湖当默认选项","body":"地图上围绕湖面的点位很多，但每一段移动、停车或步行都占时间。没有明确交通和返程安排时，先选一个片区比画一整圈更容易执行。也不必为了看某一场日落临时赶到另一侧：天气可能变化，去程之后仍有回程。只在开放且允许活动的路段停留，随现场管理及时调整。"}]',revision=revision+1 WHERE id=5 AND NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1') AND sections='[{"title":"先看距离再排计划","body":"先标出住处、古城和想去的湖岸位置，再确认交通方式。抵达与返程都需要时间，行程不宜只按照片中的感觉安排。"},{"title":"一段古城步行","body":"在古城里选择几条街道慢走，留意建筑和沿街日常。可以在自己喜欢的小店停留，也可以找一处地方休息，不必一直移动。"},{"title":"一段湖岸停留","body":"去湖岸前查天气并确认开放区域。在允许通行的路段活动，把风景、步行和休息放在同一段行程里，返程安排提前考虑。"},{"title":"出发准备","body":"注意防晒、风和天气变化。餐饮与交通花费可以按自己的实际安排记录，实时开放与交通信息请查询官方渠道。"}]';
UPDATE guides SET sections='[{"title":"先熟悉入口与方向","body":"抵达后先看街区导览，留意返回的位置。随步行观察建筑立面和铺面，不必为了寻找某个机位而忽略其他空间。"},{"title":"参观与休闲分开","body":"锦里街区与周边博物馆有不同的参观安排。如果计划结合游览，请分别查询开放与入园信息，再按自己的体力和兴趣分配时间。"},{"title":"选择真正感兴趣的体验","body":"用餐、购物与体验项目可以按喜好取舍，先看明码标价再做决定。留出坐下来休息的时间，行程也会更从容。"},{"title":"热闹之外的一条观察线","body":"先看街道转角怎样形成视线，再看门头与匾额，最后选一处停下来比较建筑与当代商业的关系。锦里具有仿古街区的营造背景，不应把每一处构件都当作原址原状的古代遗存。理解这种表达方式后，仍然可以欣赏街区的层次、民俗与日常使用，而不必依靠夸张的“穿越感”来描述。"},{"title":"如果还要参观博物馆","body":"先完成博物馆需要预约、入园或讲解的部分，锦里的休闲步行放在另一段；也可反过来安排，但不要用街区停留挤占已确定的参观时段。午餐、等位与返回都预留时间。与同伴同行时先商量这次偏阅读还是偏休闲，选择一种为主，另一种减少数量，半天就不会变成连续赶场。"},{"title":"用小份体验收尾","body":"准备尝小吃或体验项目时，先问份量、价格与等待方式；不必沿路每家都停。已经安排正餐就只加少量，想购物则把用餐留给坐下来的一段。人多时约定清晰集合点，保留返回公共交通的位置，买完东西后也不用为了走到地图尽头继续折返。"}]',revision=revision+1 WHERE id=6 AND NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1') AND sections='[{"title":"先熟悉入口与方向","body":"抵达后先看街区导览，留意返回的位置。随步行观察建筑立面和铺面，不必为了寻找某个机位而忽略其他空间。"},{"title":"参观与休闲分开","body":"锦里街区与周边博物馆有不同的参观安排。如果计划结合游览，请分别查询开放与入园信息，再按自己的体力和兴趣分配时间。"},{"title":"选择真正感兴趣的体验","body":"用餐、购物与体验项目可以按喜好取舍，先看明码标价再做决定。留出坐下来休息的时间，行程也会更从容。"}]';
UPDATE guides SET sections='[{"title":"先选一件最想做的事","body":"先想清楚这次出行最期待的是风景、建筑还是一次安静的散步，再围绕这个重点选目的地。其他内容可以放在候选清单。"},{"title":"把路程写进行程","body":"抵达、步行、排队、休息和返回都需要时间。先在地图上确认距离，再把时间留得宽松一些，遇到喜欢的地方才能从容停留。"},{"title":"核对会变化的信息","body":"门票、开放、天气和交通属于会变化的信息，出发前查看官方渠道。收藏攻略只是准备的一部分，也可以在评论里交流自己的疑问。"},{"title":"给计划设一个删减顺序","body":"先分“必去、可选、下次”三层，再排每半天。以西湖为例，必去可以是一段湖岸，可选可以是游船，下次可以是另一个片区；遇到天气、人流或体力变化，先删可选项，而不是先删用餐与返程。把结束位置和返回方式写清，计划就有了随时收尾的出口。"},{"title":"用半天预算代替全天堆点","body":"把半天可用时间依次分给抵达、重点游览、用餐休息和返回，剩余时间才考虑加点。预算同样分成必要交通、餐食、已核实的收费项目与机动，不填未经查询的票价。出发前逐项核对变化信息，回来后记录真实花费和路程，下一次才能用自己的经验调整。"},{"title":"同行的人决定行程细节","body":"先询问同伴能接受的连续步行时间、对楼梯的感受、口味与最想看的内容，再决定同日组合。有人想拍照、有人想读展签时，可以约定一个共同重点和一段自由停留。调整路线不是失败；能让每个人知道下一步、什么时候休息和怎样返回，才是一份真正可用的攻略。"}]',revision=revision+1 WHERE id=7 AND NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1') AND sections='[{"title":"先选一件最想做的事","body":"先想清楚这次出行最期待的是风景、建筑还是一次安静的散步，再围绕这个重点选目的地。其他内容可以放在候选清单。"},{"title":"把路程写进行程","body":"抵达、步行、排队、休息和返回都需要时间。先在地图上确认距离，再把时间留得宽松一些，遇到喜欢的地方才能从容停留。"},{"title":"核对会变化的信息","body":"门票、开放、天气和交通属于会变化的信息，出发前查看官方渠道。收藏攻略只是准备的一部分，也可以在评论里交流自己的疑问。"}]';
UPDATE guides SET sections='[{"title":"先分清两种体验","body":"西湖与寺院的游览方式不同。选湖岸散步时，把重点放在步行和停留；安排灵隐参观时，提前了解入园与预约要求，并给山林环境和建筑留时间。"},{"title":"把换乘和休息算进去","body":"先查询起终点之间的实际交通，再决定放在同一天还是分开。一天内组合时，两段中间留出吃饭、换乘与休息的时间。"},{"title":"看建筑，也照顾自己的节奏","body":"在寺院沿现场导览行走，先观察空间，再读说明。遇到有兴趣的细节可以多停留，天气和体力变化时也可以减少安排。"},{"title":"出发前的核对清单","body":"确认天气、返程方式与不同场所的官方入园信息。旅行攻略提供玩法思路，不替代当天的开放与交通公告。"},{"title":"湖岸与山林如何分成两天","body":"第一天以西湖步行为主，起终点选择容易到达的位置，不默认完成环湖；第二天留给灵隐及附近已经核实的参观区域。若只能同一天，先选各一小段，中间留午餐和换乘。寺院区域的入园与山路条件分别确认，避免在走完较长湖岸后临时加入体力要求更高的路线。"},{"title":"用远近视线串起两种体验","body":"湖边先看开阔水面与远山，再看堤桥怎样进入画面；山林中则先看殿宇与树木的遮挡关系，再近读建筑细节。记录两种空间里让自己停下来的原因，旅行就有了一个可以回想的主题。遇到天气变化时宁可只完成一种观看，不要求两类照片都在当天收齐。"}]',revision=revision+1 WHERE id=21 AND NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1') AND sections='[{"title":"先分清两种体验","body":"西湖与寺院的游览方式不同。选湖岸散步时，把重点放在步行和停留；安排灵隐参观时，提前了解入园与预约要求，并给山林环境和建筑留时间。"},{"title":"把换乘和休息算进去","body":"先查询起终点之间的实际交通，再决定放在同一天还是分开。一天内组合时，两段中间留出吃饭、换乘与休息的时间。"},{"title":"看建筑，也照顾自己的节奏","body":"在寺院沿现场导览行走，先观察空间，再读说明。遇到有兴趣的细节可以多停留，天气和体力变化时也可以减少安排。"},{"title":"出发前的核对清单","body":"确认天气、返程方式与不同场所的官方入园信息。旅行攻略提供玩法思路，不替代当天的开放与交通公告。"}]';
UPDATE guides SET sections='[{"title":"先在公园停一会儿","body":"可以先熟悉园内步道，挑一段适合自己的湖边路。如果想坐茶社，先确认消费方式与价格，给观察城市日常留出时间。"},{"title":"街巷选择一处重点","body":"宽窄巷子和锦里有不同的建筑与街区氛围。时间有限时，先选一处认真逛，再根据交通和体力决定是否追加下一处。"},{"title":"让用餐顺着行程走","body":"用餐位置尽量放在当天路线附近，选择自己真正感兴趣的食物。不要为了赶一份长名单反复穿越城市，实际交通以当天查询为准。"},{"title":"留一点自己的记录","body":"评论里可以分享具体的观察、路线安排或问题。照片中的市民、店员与其他游客也有自己的日常，拍摄前尊重对方意愿。"},{"title":"茶座停留也需要时间预算","body":"如果决定坐茶座，先问消费方式，再为它留出一段完整时间，而不是十几分钟就赶下一站。散步、找座、点单和离开都算在停留中。与宽窄巷子组合时，先约定下午最想看的一处，锦里可留到另一半天；这段行程的重点是看日常，不是三个地点之间的最短通行纪录。"},{"title":"两顿小吃怎样分配","body":"可以把担担面安排为一顿主食，钟水饺放到另一段少量尝试，具体仍看实际份量。同行口味不同，就先各自选择正餐，再分享适合分食的小吃；“少辣”之外也问清蒜、花椒和酱料。用餐顺着公园或街区的结束位置选择，让饭后能自然进入下一段，而不用反向赶路。"}]',revision=revision+1 WHERE id=22 AND NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1') AND sections='[{"title":"先在公园停一会儿","body":"可以先熟悉园内步道，挑一段适合自己的湖边路。如果想坐茶社，先确认消费方式与价格，给观察城市日常留出时间。"},{"title":"街巷选择一处重点","body":"宽窄巷子和锦里有不同的建筑与街区氛围。时间有限时，先选一处认真逛，再根据交通和体力决定是否追加下一处。"},{"title":"让用餐顺着行程走","body":"用餐位置尽量放在当天路线附近，选择自己真正感兴趣的食物。不要为了赶一份长名单反复穿越城市，实际交通以当天查询为准。"},{"title":"留一点自己的记录","body":"评论里可以分享具体的观察、路线安排或问题。照片中的市民、店员与其他游客也有自己的日常，拍摄前尊重对方意愿。"}]';
UPDATE guides SET sections='[{"title":"在卧龙岗看院落与展陈","body":"武侯祠和汉画馆可以作为了解这一片区的两个入口。前者留意建筑、碑刻与现场说明，后者从画像石中的人物、车马和纹样看起。两处的开放安排分别核对。"},{"title":"汉画馆里怎样慢慢看","body":"进馆先看导览，不急着把每一件展品都读完。选择几个感兴趣的图像，读展签、看细部，再回顾图像表达的生活与观念。拍照遵守展厅规定。"},{"title":"把医圣祠作为另一段安排","body":"医圣祠提供认识张仲景文化的不同视角。是否加入当天行程，应根据交通、实际开放和个人兴趣决定。本网站该景点使用的是历史资料照片。"},{"title":"准备与返回","body":"出发前查看各场所官方公告，查清入口和返回方式。若对人物故事感兴趣，可以在参观后再读可靠资料，把看到的内容与文字相互印证。"},{"title":"用两个问题读一件画像石","body":"先问“画面里直接能看见什么”，再问“展签怎样解释它”。人物动作、车马方向与纹样属于第一步，题材、年代及历史背景需要第二步的信息。选三件有差异的作品就足以练习这种读法，不必给每件拍照。把看见与推测分开记录，回去再查询会更清楚。"},{"title":"两天文化线的分配示例","body":"第一天可围绕卧龙岗与汉画馆，分别用建筑、图像作主题，中间留完整的午餐与休息。第二天按开放情况参观医圣祠，再整理前一天的问题；无需为凑足一天再增加远距离地点。对张仲景的阅读放在人物与纪念文化层面，相关介绍不作为诊疗和用药依据。"}]',revision=revision+1 WHERE id=23 AND NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1') AND sections='[{"title":"在卧龙岗看院落与展陈","body":"武侯祠和汉画馆可以作为了解这一片区的两个入口。前者留意建筑、碑刻与现场说明，后者从画像石中的人物、车马和纹样看起。两处的开放安排分别核对。"},{"title":"汉画馆里怎样慢慢看","body":"进馆先看导览，不急着把每一件展品都读完。选择几个感兴趣的图像，读展签、看细部，再回顾图像表达的生活与观念。拍照遵守展厅规定。"},{"title":"把医圣祠作为另一段安排","body":"医圣祠提供认识张仲景文化的不同视角。是否加入当天行程，应根据交通、实际开放和个人兴趣决定。本网站该景点使用的是历史资料照片。"},{"title":"准备与返回","body":"出发前查看各场所官方公告，查清入口和返回方式。若对人物故事感兴趣，可以在参观后再读可靠资料，把看到的内容与文字相互印证。"}]';
UPDATE guides SET sections='[{"title":"先读古城中的双塔","body":"在开元寺先看整体布局，再观察石塔和建筑细部。参观与周边街巷步行可以结合，保持安静并遵守寺院指引。"},{"title":"古桥需要单独规划","body":"洛阳桥位于泉州洛阳江上，并非从西街随意走几步就能到。先查询实际交通和返程方式，再决定安排在哪一段时间。"},{"title":"带着问题看桥","body":"可以先了解桥梁的用途与建设背景，再观察桥体、桥墩和石刻。把建筑当作历史的材料，会比只留一张照片看到更多。"},{"title":"给天气和体力留空间","body":"桥面、街巷和院落都需要步行。风雨天气及时调整，选择允许通行的区域。实际开放信息请通过官方渠道核对。"},{"title":"古城一天、古桥半天怎么选","body":"如果只有一天，先决定更想深入古城还是专程看桥，不把两者都写成必去。两天时可把开元寺、西街与用餐放在第一天，洛阳桥放在交通更从容的另一半天。要在同日组合，就先核实接驳与回程，压缩街巷闲逛数量，而不压缩过桥与观察时间。"},{"title":"在桥上看结构，在岸边看关系","body":"桥面上的步行适合观察铺装、栏杆与石刻，在开放岸边则更容易理解桥与河口、两岸的关系。两个视角可以分开安排，不需要为看桥墩自行走到非开放区域。以官方说明理解建桥技术，看到的水位、天气和通行状态只属于当天，不应写成任何人来都必有的场景。"}]',revision=revision+1 WHERE id=24 AND NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1') AND sections='[{"title":"先读古城中的双塔","body":"在开元寺先看整体布局，再观察石塔和建筑细部。参观与周边街巷步行可以结合，保持安静并遵守寺院指引。"},{"title":"古桥需要单独规划","body":"洛阳桥位于泉州洛阳江上，并非从西街随意走几步就能到。先查询实际交通和返程方式，再决定安排在哪一段时间。"},{"title":"带着问题看桥","body":"可以先了解桥梁的用途与建设背景，再观察桥体、桥墩和石刻。把建筑当作历史的材料，会比只留一张照片看到更多。"},{"title":"给天气和体力留空间","body":"桥面、街巷和院落都需要步行。风雨天气及时调整，选择允许通行的区域。实际开放信息请通过官方渠道核对。"}]';
UPDATE guides SET sections='[{"title":"古城适合近看日常","body":"选择几条街道慢走，观察建筑、院落和店铺。不要把古城只当作其他景点之间的中转点，也可以给它一段完整的时间。"},{"title":"三塔适合先看整体再看细部","body":"先从允许到达的位置观察三塔的组合，再结合展陈认识建筑与历史。参观前分别确认景区票务、开放与交通安排。"},{"title":"湖岸适合少赶路、多停留","body":"选一个明确的湖岸片区，再查询往返方式。一天内不必追求环湖所有地点，留出天气变化和休息的余量。"},{"title":"行程按实际条件调整","body":"把住宿地点和各段交通放在地图上考虑，注意防晒和风。攻略中的组合是编辑建议，实际参观安排以官方公告与现场要求为准。"},{"title":"把三个地方变成三个小任务","body":"古城挑一个街角看建筑和日常；三塔先看主塔与小塔的前后关系，再读一块展签；湖岸选一个具体位置停一段时间。每处只设一个小任务，会比在地图上连续加点更容易留下印象。想深入哪一处，就把其他内容减成候选，不要求每种观看都达到相同停留时长。"},{"title":"第三天应当用来做什么","body":"如果有三天，不必直接加入另一整圈湖岸。可用半天解决抵达、行李或天气变化，再把喜欢的片区看细一点。返程当天只安排离返回路线近的一小段，提前确认取行李、接驳与进站。照片中的光线不是可预约项目，少追一个机位，反而更有时间等待属于当天的变化。"}]',revision=revision+1 WHERE id=25 AND NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1') AND sections='[{"title":"古城适合近看日常","body":"选择几条街道慢走，观察建筑、院落和店铺。不要把古城只当作其他景点之间的中转点，也可以给它一段完整的时间。"},{"title":"三塔适合先看整体再看细部","body":"先从允许到达的位置观察三塔的组合，再结合展陈认识建筑与历史。参观前分别确认景区票务、开放与交通安排。"},{"title":"湖岸适合少赶路、多停留","body":"选一个明确的湖岸片区，再查询往返方式。一天内不必追求环湖所有地点，留出天气变化和休息的余量。"},{"title":"行程按实际条件调整","body":"把住宿地点和各段交通放在地图上考虑，注意防晒和风。攻略中的组合是编辑建议，实际参观安排以官方公告与现场要求为准。"}]';
UPDATE foods SET description='片儿川把杭州食味放进一碗热面里，适合安排在湖岸步行前后，作为一顿能坐下来慢慢吃的主食。与其把店铺排成专程往返的清单，不如先选好当天片区，再寻找附近合适的一碗。
点单可以先问面量、浇头和汤底，明确加料是否另外收费。第一口先尝汤与面，再决定是否添调料；如果还想吃葱包桧，留到另一段街巷步行，避免一顿正餐之后继续追着小吃赶。',taste='面条、汤底与浇头共同决定口感，不同店家的咸鲜和份量会有差别。点单时具体问今天的配料，忌口或希望少油少盐可先沟通，不只根据菜名判断整碗内容。',tips='建议用于湖岸游览中途或结束后的午餐，先坐下休息再继续。两人同时点多种食物时可减少加料；返程当天留足上餐与用餐时间，不端着热汤赶接驳。',revision=revision+1 WHERE id=1 AND NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1') AND description='片儿川是杭州常见的地方风味面食，也是认识杭城饮食的一条线索。旅行不一定从一桌大菜开始，一碗面也可以成为湖岸漫步与街巷游览之间的停顿。
安排时，可以先选定当天游览的片区，再在附近寻找合适的用餐地点，不必为一碗面跨城赶路。' AND taste='这是一道面食，具体浇头、汤底和调味会因店家而异。想尝原本的风味，可以先少量品尝汤和面，再按自己的口味添加调料。' AND tips='可作为午餐或散步前后的简餐。点单前看清菜单上的规格、价格和实际配料；本页不指定店铺，也不保证某家门店的营业情况。';
UPDATE foods SET description='葱包桧是杭州的小吃，以薄饼包裹油条等内容，经过压烙后形成不同于一碗面的吃法。它适合成为街巷步行中的一份加餐，重点在薄饼、馅料和酱料的组合，而不是替一整天旅行另开一条赶路线路。
购买时先问一份的大小与默认酱料，确定是否方便分食。拿到后找允许停留的位置品尝，吃完再继续走；如果刚吃过正餐，可以和同伴共享少量，把口味体验和饱足的一餐分开。',taste='薄饼、油条与酱料的组合带来不同层次，葱和调味的用量会因店家而异。喜甜、怕辣或不吃某种配料时直接问清能否调整，不根据照片推断味道。',tips='适合少量尝试，不必为了集齐小吃打乱西湖或寺院安排。确认现做等待和加料价格；包装会有温度，先找好停留处再食用，勿将食物包装留在湖岸或街巷。',revision=revision+1 WHERE id=2 AND NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1') AND description='葱包桧是杭州的地方小吃，以薄饼包裹油条等食材制成。杭州亚运会官方资料曾用“薄饼裹着油条”解释它的名字，适合作为初识这道小吃的直观入口。
逛街时可以把它放在正餐之外，作为一份小点心，不必把吃小吃也安排成赶时间的打卡。' AND taste='薄饼与油条带来不同的口感层次，具体酱料与做法请以现场为准。刚制作完成时留意温度，先小口尝试。' AND tips='可与同行的人分着尝，给后面的正餐留出胃口。购买前确认一份的数量、配料和标价，酱料有要求时先与店家说明。';
UPDATE foods SET description='钟水饺是认识成都小吃的一条线索，商务部老字号资料介绍了红油与清汤等品种。它可以是一餐中的一小份，也可以与其他食物分次安排；想了解地方风味时，先感受饺子与调味的关系，再决定是否继续加点。
旅行点单时先确认口味、个数和份量。红油版本并不只是“辣”，甜咸与蒜香也会影响体验；同行口味不同，可以各选适合自己的调味，不必为共享一份勉强所有人接受同一辣度。',taste='老字号资料中的红油品种偏鲜香、咸中带甜，清汤则是另一种选择；具体门店供应与做法须现场确认。馅料、蒜和辣油有忌口时提前询问，不能把所有红油小吃当作相同口味。',tips='可放在街区步行结束后的休息段，先问每份数量再决定是否另点面食。不用把“少辣”当成全部要求，可具体问辣油或蒜是否分放；点餐后预留完整用餐时间。',revision=revision+1 WHERE id=3 AND NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1') AND description='钟水饺是成都的传统小吃。商务部老字号数字博物馆介绍了红油与清汤两类代表风味，体现出成都面点在做法与调味上的不同层次。
旅行中可以把它作为一餐中的一种选择，配合当天的街巷与公园安排，留出坐下来慢慢吃的时间。' AND taste='官方资料介绍，红油口味兼有鲜香、微辣与回甜，清汤做法则偏鲜美。传统水饺使用猪肉馅；实际配方和辣度仍需向所选店家确认。' AND tips='先询问红油或清汤、份量与辣度，再按自己的口味选择。网站介绍的是地方食物，不代表某家门店当前的价格、配料或营业时间。';
UPDATE foods SET description='担担面是成都地方面食的一种旅行入口，一份面中的面条、臊子和调味可以一起体验。把它作为正餐还是小吃，取决于实际份量与自己饭量，名称本身不能说明一碗是否足够。
先选好当天游览片区，再找顺路的用餐处。点单时确认口味与份量，上桌后先尝少量，再按店家建议拌匀；如果还想品尝钟水饺，分到另一顿或共享小份，留出休息比连续赶几家店更舒服。',taste='不同店家在辣油、花椒、臊子和酱料上的处理不同，不能只凭红色判断麻辣程度。对某种配料有忌口时问清实际做法，是否可调辣也由门店确认。',tips='安排在宽窄巷子、锦里等行程附近的一餐即可，不推荐未经核实的固定商家排名。先问小份与标准份的区别、加料价格，再决定点多少；口味偏重时也无需勉强吃完。',revision=revision+1 WHERE id=4 AND NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1') AND description='担担面是成都具有代表性的小吃之一。四川省政府的美食资料介绍了细面条搭配肉末等材料的做法，是了解成都日常面食的一种入口。
把面食安排在行程中的合适时段，比一次连续尝很多种食物更容易保留各自的味道。' AND taste='资料所述风味以咸鲜、微辣为特点，面条与浇头拌匀后再吃，更容易尝到不同部分的组合。具体辣度、配料和汤汁多少因店家而异。' AND tips='点餐前说明能接受的辣度，先了解碗的大小和份量。想继续吃其他小吃时，可优先选择小份，而不是为了打卡勉强加餐。';
UPDATE foods SET description='南阳牛肉汤适合放在参观前后作为一餐的组成。旅行里认识一座城，有时不需要一次点满一桌菜，坐下来喝一碗汤、了解配饼和加料方式，也能给人文游览留一个日常的切口。
先询问肉量、汤份与配饼是否分别计费，再决定是否增加主食。若当天要看武侯祠或汉画馆，把用餐安排在容易返回路线的位置，餐后留一点休息时间，不在吃完后立即赶进下一处场馆。',taste='汤底、肉量和调味因店家不同而变化。可以先尝原汤，再决定加多少辣椒、胡椒或其他调料；若有忌口，点单时询问实际配料，而不根据“清汤”字样自行判断。',tips='和同伴点餐时先估主食份量，避免配饼与另一碗面重复堆叠。参观日优先顺路用餐，出发前确认店铺具体位置与营业情况，不把网上常见店名当作当天可用的确定信息。',revision=revision+1 WHERE id=5 AND NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1') AND description='南阳市政府的地方美食目录收录了南阳牛肉汤。比起将城市的味道只理解为宴席，一碗日常汤食也能提供另一种认识地方生活的方式。
可把用餐与当天的人文游览分开留出时间，吃完再继续走，不必把食物变成匆忙的一站。' AND taste='以牛肉汤食为认识起点，汤底、配料与调味由实际店家决定。可以先尝原汤，再按自己的口味添加调料。' AND tips='购买前问清份量、配料和价格。若对肉类、调味或搭配有要求，请先说明，也可以先尝原汤，再按自己的口味添加调料。';
UPDATE foods SET description='新野板面是南阳所辖新野县的一条地方食味线索。它适合从面条、臊子与汤的搭配去理解，而不是只把“新野”当作南阳市区的一条街；找店时先核对实际地址，区分风味名称与所在位置。
如果行程只安排南阳市区人文场馆，可在顺路范围内查询是否有合适店铺，不必为一碗面临时增加跨县往返。点单先说明饭量和能接受的口味，等一碗面坐下来吃完，再开始下一段参观。',taste='面条与肉臊子的搭配是理解这道风味的入口，辣度、配菜和汤的浓淡依门店而异。询问实际使用的肉类与调味，偏清淡时确认是否能调整，不把一种店家的做法当作统一标准。',tips='先看店铺位置、份量与标价；“新野板面”不代表所有门店就在新野，也不代表市区景点旁必定有售。有限行程优先顺路，想专程去新野则另作一段完整计划。',revision=revision+1 WHERE id=6 AND NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1') AND description='新野板面是南阳新野县的地方面食。新野县政府资料介绍了摔面、臊子熬制等制作环节，面条与臊子的组合构成了这份食味的重要部分。
新野属于南阳所辖县，并不等同于南阳城区。寻找具体门店或安排前往新野时，应单独核对地图位置与交通。' AND taste='可以先观察面条的形态、尝面与汤汁的组合，再决定是否继续添加调料。实际肉类、蔬菜及辣度请以所选店家说明为准。' AND tips='适合作为一餐主食来安排。点单时先问规格和实际配料，不根据菜名推断门店位置；这一条介绍不意味着需要专程跨片区赶路。';
UPDATE foods SET description='面线糊是泉州常见的小吃，细面线与汤底构成基础，再按店家供应搭配不同配料。它可以成为古城步行前的一份早餐，也可以作为参观间隙的一次坐下休息；吃什么、加多少，应先看现场菜单。
初次点单可从少量配料开始，先理解汤与面线的口感，再决定下次想换哪种搭配。配料并非越多越能代表当地味道，点齐一长串之前，先确认基础份、加料和配食分别多少钱。',taste='汤底与加料可能涉及肉、海产品、蛋等不同食材，具体内容由店家确认。胡椒和其他调味也会影响口感，有忌口时在下单前询问，不能只根据碗里看见的配料推断汤底。',tips='适合与开元寺、西街游览分段安排，吃热汤时坐稳后再开始，勿边走边端碗。若之后还想尝肉粽，先减少这一餐的加料；确认结账明细，给用餐留下完整时间。',revision=revision+1 WHERE id=7 AND NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1') AND description='面线糊是泉州的地方小吃。泉州美食官方资料介绍了细面线、汤底与不同配料组合的做法，也呈现了这道食物在街巷日常中的位置。
认识一座城时，留出一顿不赶时间的饭，有时比多走几个打卡点更能记住它的节奏。' AND taste='面线与汤汁形成细软的口感，可选择的配料较多，不同门店做法各有差异。选择配料前先确认名称、价格与自己的接受程度。' AND tips='初次品尝可从简单搭配开始，避免一次加太多而分不清各自的味道。用餐时间、营业与位置请自行向具体门店核实。';
UPDATE foods SET description='烧肉粽是泉州地方小吃的一种，糯米与不同馅料组合，适合从口感、馅料和蘸酱三个层面慢慢尝。与一碗面线糊相比，它更容易让一顿“小吃”变得饱足，点单时需要先看大小。
可选一个作为正餐中的主食，或者和同伴分食少量。把肉粽安排在古城步行中的休息段即可，不必为了同时集齐几种小吃重复穿行街巷；吃完之后再决定是否继续加点。',taste='不同店家使用的肉、菇、海产品等馅料和蘸酱并不完全相同。先询问一份内容，尝原味后再加酱；有食材忌口时同时确认馅料与酱料，而不只问是否有肉。',tips='先看大小与每份价格，再决定是否另点主食。想带走时确认保存和食用方式，按店家实际说明处理；不要把适合现吃的旅行小吃默认当成可长途常温携带的伴手礼。',revision=revision+1 WHERE id=8 AND NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1') AND description='泉州市政府的特色小吃资料介绍了烧肉粽，以糯米搭配肉类、香菇等馅料包裹制作。不同配料的组合，是这份地方风味值得细看的部分。
旅行中可以将它作为一份饱腹的小吃，安排在逛城的间隙，也可以按实际份量决定是否作为一餐。' AND taste='糯米与馅料形成软糯、咸香的组合。所含肉类、海味及其他配料因店家而异，请在购买前确认。' AND tips='先看清粽子的大小和价格，再按自己的食量选择。刚出锅时留意温度；如果还准备尝其他小吃，可以先选一份与同行的人分享。';
UPDATE foods SET description='乳扇是以牛奶制作的大理白族风味食品，薄片形态与奶香是认识它的入口。烤、煎等不同做法可能带来不同体验，旅行时不必一次吃很多，可以先少量尝试，再判断是否喜欢这种风味。
在古城街巷或当天用餐附近选择合适供应即可，不为一份点心临时改换湖岸片区。点单先问做法、酱料与份量，和同伴分享时把奶香与甜味的接受程度说清楚，避免只根据外形作判断。',taste='乳扇本身属于乳制品，奶香与口感会受加工方式影响。是否加甜酱、用什么油或配料都需现场确认；对奶类有忌口时先了解实际内容，不把“点心”理解成不含乳成分。',tips='适合作为古城步行中的少量加餐，不必替代完整正餐。准备购买包装产品时查标签、储存和携带条件，不照搬网络介绍中的保存天数；购买数量以实际需要为准。',revision=revision+1 WHERE id=9 AND NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1') AND description='大理市政府特产资料介绍，乳扇是大理白族的风味食品，可有煎、烤等不同食用做法。图片展示的是乳扇本体，并不是某家店的烤乳扇成品。
选择怎样品尝时，可以先问清制作方式和搭配，再决定把它作为一份小吃，还是与其他食物一起分享。' AND taste='乳香是认识它的重要线索，具体口感与是否加糖、加酱，取决于实际制作方式。点餐时先确认原料和调味。' AND tips='可以少量尝试不同做法，不需要为尝一种食物打乱整个行程。图片摄于大理州洱源，并不代表大理古城某家门店的现售菜品。';
UPDATE foods SET description='巍山耙肉饵丝是大理州巍山的一种地方风味，可以从饵丝、肉与汤的搭配认识当地饮食。它与大理古城、洱海分属不同旅行片区，菜名中的地方身份值得了解，也提醒规划时先确认距离。
如果只在古城和湖岸停留，可查询当天顺路范围是否有供应，不把品尝一种味道自动变成专程去巍山。若本来就计划巍山行程，则把这碗饵丝放进一餐，和街巷参观、坐下休息一起安排。',taste='饵丝与汤、肉的搭配呈现不同于普通面条的口感，具体肉量和调料依门店而异。先询问份量与所用配料，再按自己的偏好加调味；实际售卖内容不只由菜名决定。',tips='先核对店铺在大理古城周边还是巍山县，跨片区用餐需要完整去返时间。上餐、用餐与后续接驳都算进行程；想继续尝乳扇时分开餐次，不用一餐完成所有地方风味。',revision=revision+1 WHERE id=10 AND NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1') AND description='耙肉饵丝是大理州巍山地方小吃之一，云南省民族宗教事务委员会介绍巍山小吃时也提到这一食物。它提供了古城与湖岸之外，认识大理州饮食的另一条线索。
巍山县不在大理古城内。若想前往当地品尝，应将它作为独立的出行安排，而不是把州内不同县市当作同一个步行片区。' AND taste='饵丝与肉汤形成一份主食组合。实际肉类、汤底、调味和份量请向店家确认，适合先尝原味再按需要加调料。' AND tips='配图为大理州巍山耙肉饵丝。查找店铺时核对所在县市和返回交通；网站不保证某家门店当前的菜单、营业或价格。';
INSERT OR IGNORE INTO guides(id,city_id,title,subtitle,intro,image,source_url,theme,duration_minutes,sections) SELECT 101,1,'第一次去杭州，两天怎样安排更从容','从抵达到返程，把湖岸、山林和一碗面放进同一份计划','适合第一次到杭州、希望兼顾西湖与寺院又不想赶路的人。用两个半天重点和两个弹性时段搭框架，再根据抵达时间、天气与体力调整。','/assets/hangzhou-lake.jpg','https://whc.unesco.org/en/list/1334/','山水风景',960,'[{"title":"先解决住在哪里和怎样抵达","body":"先把到达车站、住处、西湖起点和灵隐参观位置标到同一张地图上，比较实际接驳，而不只搜索“西湖附近住宿”。有大件行李时先安排寄放或入住，再开始步行；抵达当天较晚，就把原计划缩成一小段湖岸，不把赶到城市的疲惫继续叠到山林参观里。"},{"title":"第一天：一段湖岸，而非一整圈","body":"上午或抵达后的完整半天留给西湖。先选方便到达的起点，再选容易返回的终点，沿途安排一次坐下休息。观察可以从远处山城关系开始，再看桥与堤怎样进入画面。想乘船时查清具体项目与返回点，并减少后续步行；不把候船时间从午饭和返程里扣掉。"},{"title":"第二天：寺院参观单独留时间","body":"灵隐一带按具体区域核对入园与预约，先参观最想看的部分，再决定是否增加周边安排。山林和台阶带来的体力消耗与平坦湖岸不同，带长辈同行时尤其需要先商量。结束后找顺路地点吃饭，留下半天应对天气变化或早点返回，不必再次跨片区补打卡。"},{"title":"餐食与花费按场景记录","body":"片儿川可作为坐下来的正餐，葱包桧放在另一段少量加餐。交通、餐食、已确认的收费项目和机动分开估算，票价与实际供应出发前查询，不用网上的旧价格拼出看似精确的预算。两人同行先问份量，再决定是否加小吃，给饭后休息留时间。"},{"title":"遇到雨天，优先调顺序","body":"若天气更适合湖岸的一天已经明确，可把户外步行放到那天；寺院也不是完全不受天气影响的室内替代，仍要看步道、台阶与现场开放情况。强降雨时删掉户外段，休息或改期；轻雨则缩短路段，看近处水面与建筑。不要为“来都来了”勉强完成原表格。"},{"title":"返程半天只保留容易收尾的内容","body":"提前确定取行李、到车站和进站所需时间，再把剩余部分用于住处附近的一餐或短步行。把最后一段湖岸写成可选项，走累或天气变化时直接取消。回顾时记录一次最喜欢的停留和一段实际接驳，下次的路线会比复制别人的全天打卡单更适合自己。"}]' WHERE NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1');
INSERT OR IGNORE INTO guide_spots(guide_id,spot_id,sort_order) SELECT 101,1,0 WHERE NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1') AND EXISTS(SELECT 1 FROM guides WHERE id=101 AND title='第一次去杭州，两天怎样安排更从容');
INSERT OR IGNORE INTO guide_spots(guide_id,spot_id,sort_order) SELECT 101,21,1 WHERE NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1') AND EXISTS(SELECT 1 FROM guides WHERE id=101 AND title='第一次去杭州，两天怎样安排更从容');
INSERT OR IGNORE INTO guides(id,city_id,title,subtitle,intro,image,source_url,theme,duration_minutes,sections) SELECT 102,1,'西湖摄影散步：用三种距离看一段湖岸','远景看关系，中景看堤桥，近景看树影与水面','不追逐固定机位，也不依赖一定出现的日落。沿一段可完成的湖岸，把一张风景照变成三种不同观看方式，适合喜欢拍照又希望走得轻松的人。','/assets/hangzhou.jpg','https://whc.unesco.org/en/list/1334/','山水风景',240,'[{"title":"先给散步划一条可以完成的边界","body":"在地图上选定一个容易到达的起点和一个方便返回的终点，只把这一段作为本次拍摄范围。开始前看天气与现场通行情况，预留一段坐下整理照片的时间。不要一开始就追求横跨多个湖岸，也不把网上一张照片的位置当作必须找到的唯一答案。"},{"title":"远景：让山、湖与城市产生关系","body":"先把注意力从手机屏幕移开，看看远山、水面与城市分别占据什么位置，再选择取景。可以试着让同一处景色有两种构图：一张多留水面，一张加入近处树木，回看哪一种更能表达你看到的空间。这是观看练习，不需要走到岸线外寻找无遮挡位置。"},{"title":"中景：用堤桥和行走方向组织画面","body":"走近之后看看道路、堤岸或桥如何把视线引向远处，试着从正常通行位置拍一张有前后层次的照片。人多时可以接受画面中有人，把真实的行走节奏作为环境的一部分；拍完及时移动，不在狭窄处反复停留等待所谓的空镜。"},{"title":"近景：天气不完美时也有内容","body":"树影、桥栏、落在叶面上的水和岸边细部，可以在阴天成为观察重点。先看一会儿，再决定是否值得拍，不必每走几步都举起手机。雨势变大时停止临水取景，收好设备往预定返程点走，近景练习不是继续冒雨赶路的理由。"},{"title":"让三张照片形成一组记录","body":"从拍到的内容中各选一张远、中、近景，给每张写一句位置关系或当时的观察。避免只写“绝美”“必来”，改成“树影让桥面分成明暗两段”这样可回想的细节。画面里有清晰人物时尊重对方意愿，不把他人的日常当作可以随意发布的素材。"},{"title":"拍完以后就可以结束","body":"一组能说明问题的照片已经足够，不需要等到天黑或走遍一圈。把用餐选在终点或返程附近，检查交通再离开。日落、倒影与水面状态都不能保证，计划的完成条件应是好好看过这一段湖岸，而不是复制某个固定时刻的光线。"}]' WHERE NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1');
INSERT OR IGNORE INTO guide_spots(guide_id,spot_id,sort_order) SELECT 102,1,0 WHERE NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1') AND EXISTS(SELECT 1 FROM guides WHERE id=102 AND title='西湖摄影散步：用三种距离看一段湖岸');
INSERT OR IGNORE INTO guides(id,city_id,title,subtitle,intro,image,source_url,theme,duration_minutes,sections) SELECT 103,2,'不太吃辣，也能安排一段成都食味之旅','先选合适口味，再让小吃顺着公园与街巷出现','适合想尝成都小吃、又不愿把每一顿都变成辣度挑战的人。用钟水饺与担担面作为线索，练习问清调味、份量和加料，让一餐真正适合自己。','/assets/chengdu-park.jpg','https://lzhbwg.mofcom.gov.cn/edi_ecms_web_front/thb/detail/8cf137a439d24c3a8ed22112e6243665','街巷生活',480,'[{"title":"先说具体需求，而不只说少辣","body":"点单前问清辣油、蒜、花椒或酱料是否能调整，哪些已经拌入、哪些可以分放。有人不吃某种食材时，直接说明实际忌口，再确认门店能否满足。旅行中的口味选择不需要与别人比较，也不用为了“体验地道”勉强点一份自己无法接受的食物。"},{"title":"钟水饺不只有一种入口","body":"老字号资料介绍了红油与清汤等不同品种，红油的特点也不仅在辣，还涉及甜咸与蒜香。实际供应以门店为准，可以先确认是否有适合的版本，再问一份多少个、是否适合作为正餐。先少量尝试，决定是否加点，而不是看到小吃两个字就默认份量很小。"},{"title":"担担面放到另一顿更容易取舍","body":"想比较两种面食，可以把担担面与水饺分到不同餐次，或者各点小份并由愿意分食的同伴共享。点单先问臊子与调味的实际内容，上桌后先尝一口，再决定怎样拌匀。不同店家的调味有差异，不能用一次体验给整座城市的食物下结论。"},{"title":"公园到街巷，让饭点成为中场","body":"可先在人民公园散步或停坐，再按实时交通转往宽窄巷子，用餐放在两个活动之间。这样饭前不用携带过多食物赶路，饭后也有机会调整下午的步行量。茶座另看消费方式，正餐另算份量，不把喝茶、小吃与一整顿饭在计划里都省略成十分钟。"},{"title":"同行口味不同，就分开选择主食","body":"先各自点适合的一份正餐，再共享少量大家都愿意尝的小吃，比要求全桌接受同一辣度更轻松。不要把清汤等名称直接等同于无某种配料，仍需询问。食物偏好与旅行节奏一起商量：有人想休息时，就减少店铺数量，而不是一边吃一边继续赶下一家。"},{"title":"用一次完整的体验代替一张长清单","body":"记录这顿饭的具体份量、调味和是否适合自己，下次才能作比较。价格、营业和菜单会变，出发前再核对门店，不把攻略当作当天供应保证。结束后从方便接驳的位置返回，留下一两种没吃到的食物也没关系，它们可以成为下一次来成都的期待。"}]' WHERE NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1');
INSERT OR IGNORE INTO guide_spots(guide_id,spot_id,sort_order) SELECT 103,22,0 WHERE NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1') AND EXISTS(SELECT 1 FROM guides WHERE id=103 AND title='不太吃辣，也能安排一段成都食味之旅');
INSERT OR IGNORE INTO guide_spots(guide_id,spot_id,sort_order) SELECT 103,2,1 WHERE NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1') AND EXISTS(SELECT 1 FROM guides WHERE id=103 AND title='不太吃辣，也能安排一段成都食味之旅');
INSERT OR IGNORE INTO guides(id,city_id,title,subtitle,intro,image,source_url,theme,duration_minutes,sections) SELECT 104,2,'成都周末两日：公园、街巷与半天空白','把人民公园、宽窄巷子和锦里分成可以取舍的段落','适合周末短住、想同时看看建筑和城市日常的人。每天只保留一个主要片区和一个可选项，给茶座、用餐、抵达与返回留出真正的时间。','/assets/chengdu.jpg','https://cd3000y.cccic.org.cn/views/3DMuseum/OldStreet.aspx','街巷生活',960,'[{"title":"抵达之前：先认清三个位置","body":"把人民公园、宽窄巷子与锦里放到同一张地图，再加住处和到达车站。三者虽然都属于城市游览，也不是不用转场的一条连续步行街。按自己的抵达时间决定第一天能完成哪一段，晚到时只保留公园或一处街巷，不在下车后立即开始全天打卡。"},{"title":"第一天上午：走一段，再坐一会儿","body":"人民公园先选一小段步道，熟悉环境后再决定是否坐茶座。若选择停坐，就给点单、喝茶和离开留出完整时间，不把茶座当作几分钟拍照的背景。消费项目先看价格，人物拍摄尊重他人；如果当天不想消费，正常公园散步同样可以成为重点。"},{"title":"第一天下午：院落比店铺数量更值得比较","body":"按实际接驳前往宽窄巷子，先用一条巷子熟悉入口与方向，再比较另外街巷的门头、院落与尺度。用餐安排在转换片区前后，按份量选择小吃。逛店与看建筑不必同时追求数量，选两三处真正感兴趣的位置，留一个方便返回的结束点。"},{"title":"第二天：锦里与文化参观各占一段","body":"锦里偏街区休闲，周边博物馆参观另查开放与入园安排。想认真读展陈，就先留文化参观的完整时段，锦里只走一小段；想轻松逛街，则减少另一项。仿古营造和历史遗存需要分别理解，既可以看建筑表达，也不用把每一个构件都当作古代原物。"},{"title":"那半天空白可以怎样使用","body":"空白首先用来承接迟到、天气、临时休息和喜欢某一处而多停留，并非必须填满的待办格。雨大时减少露天街巷，可改为已核实开放的室内参观或一顿完整的饭；如果两个重点已经看得满足，就早点回住处整理照片与实际花费。"},{"title":"返程前删掉最后一个可选项","body":"先倒推取行李、接驳与进站，剩余时间再决定短步行或用餐。与同伴事先约定必看项和集合点，临时分开逛也知道如何联系。两天结束时记住一处院落、一段公园日常和一道适合自己的食物，通常比三个地方都只留下门口照片更有内容。"}]' WHERE NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1');
