INSERT OR IGNORE INTO guides(id,city_id,title,subtitle,intro,image,source_url,theme,duration_minutes,sections) SELECT 105,3,'第一次看汉画像石：在汉画馆读懂三件作品','从画面、动作与展签入手，让博物馆参观有一条线索','不需要提前背完汉代历史，也能展开一次有内容的参观。用三件作品练习观察，把看见的内容、展签解释与自己想问的问题分开记录。','/assets/nanyang-han.jpg','https://www.wolong.gov.cn/2025/01-13/1037195.html','人文历史',240,'[{"title":"进馆先决定这次看什么","body":"先查当天开放与入馆要求，进馆后读导览，再从人物、车马或装饰纹样中选择一条主题。不是每一件作品都必须看完，也不必按手机里的图片逐件寻找。给自己一到两个小时慢看与休息，再留下参观后的整理时间；跟随讲解时按实际节奏调整。"},{"title":"第一件：只描述画面里能看见的内容","body":"先不急着判断人物身份，观察画面分成几部分、人物朝向哪里、哪些线条重复出现。用自己的话写两三句客观描述，再读展签看有哪些信息得到补充。分清看见的与后来知道的，既能减少想当然，也更容易发现自己原来没有注意到的细节。"},{"title":"第二件：比较动作与空间","body":"选一件构图或动作不同的作品，比较人物、车马或纹样怎样安排位置，哪些部分更突出、哪里更密集。无需给雕刻技法下专业结论，先把差异说清即可。站在正常观看位置看整体，再靠允许的距离看细节，不触摸石面，也不为拍清纹理违反展厅规定。"},{"title":"第三件：带着展签的信息回看","body":"这次可以先读展签，再看画面，试着指出解释中提到的具体部分。题材、年代与出土背景等信息依馆方说明理解，有疑问就记下原文的关键线索，回去再查可靠资料。不要把一件作品的解释直接套到全部画像石，差异本身就是值得看的内容。"},{"title":"带孩子或同伴可以怎样交流","body":"每个人挑一件最想介绍的作品，只说三点：看到了什么、哪处最有意思、还有什么没弄明白。先允许不同观察，再一起读展签，不用比赛谁背出更多人物。交流保持展厅音量，想拍照或记录先看规定；同伴疲惫时减少作品数量，一次完整比较已经足够。"},{"title":"把这段参观接到城市里","body":"汉画馆可与卧龙岗片区一起考虑，但两处的开放和入口分别核对。上午看建筑、下午看图像是一种编辑安排，也可按实际条件反过来；中间留出用餐与休息。如果当天只看汉画馆，就把剩余时间用于整理三件作品的记录，不必为了填满半天再匆匆加一个场所。"}]' WHERE NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1');
INSERT OR IGNORE INTO guide_spots(guide_id,spot_id,sort_order) SELECT 105,23,0 WHERE NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1') AND EXISTS(SELECT 1 FROM guides WHERE id=105 AND title='第一次看汉画像石：在汉画馆读懂三件作品');
INSERT OR IGNORE INTO guides(id,city_id,title,subtitle,intro,image,source_url,theme,duration_minutes,sections) SELECT 106,3,'南阳两天人文线：把院落、图像与人物分开读','卧龙岗与汉画馆一天，医圣祠另留一段，给阅读留出时间','适合喜欢古建和展陈、希望一次参观能记住一些细节的人。用三种阅读方式组织两天，而不是把三个场所当作需要连续打卡的名单。','/assets/nanyang-temple.jpg','https://lyj.nanyang.gov.cn/2023/09-19/175434.html','人文历史',960,'[{"title":"出发前先做三项核对","body":"核对正式场所名称和入口、当天开放与预约、住处到各处的实际交通。南阳武侯祠与成都同名场所不同，医圣祠页面中的历史照片也不能作为今天找门的依据。把可能需要的公告保存下来，再围绕确定能参观的部分排顺序；不凭几张照片判断一日通行安排。"},{"title":"第一天上半段：用空间理解武侯祠","body":"按现场导览观察院落的推进关系，挑一处建筑和一块碑刻细读。给自己一个具体问题，例如哪段文字解释了建筑的用途，再把看到的与查到的资料相互印证。没有必要逐字识完全部碑刻；若有正式讲解，可按个人兴趣了解安排，并给结束后的回顾留时间。"},{"title":"第一天下半段：给汉画馆换一种看法","body":"两处之间保留午餐与休息，再在汉画馆选人物、车马或纹样中的一条主题。每类不用看很多，选三件有差异的作品做比较，读展签后再回看画面。入口与开放要求分别确认，午后疲惫时减少作品数量，不用快速穿过全部展厅来证明自己已经看过。"},{"title":"第二天：把人物纪念单独留一段","body":"医圣祠从人物生平、纪念空间与展陈说明切入，先看当日导览，再选择一段内容阅读。它与卧龙岗片区之间另算去返，参观后可以用一顿顺路的饭收尾。有关张仲景的文化介绍用于理解人物纪念，不作为个人诊疗或用药依据，也无需把参观写成养生体验。"},{"title":"两顿饭如何顺着参观走","body":"牛肉汤可以结合参观前后的正餐，先问配饼、肉量和加料。想尝新野板面时先核对店铺地址，新野县和市区景点不是一个步行片区；行程紧时优先找顺路用餐，不为菜名临时赶一趟跨县交通。吃完稍作休息，再开始下一段阅读或返回。"},{"title":"最后用三条记录整理旅行","body":"分别记下一个建筑细节、一幅画像石和一句人物介绍，再把不确定的问题列成待查清单。这样的回顾比一页密集的地点列表更能留下内容。若天气或开放变化导致少看一处，就把那一处留给下次；两天计划的价值在于阅读从容，而不是所有名称都被勾选。"}]' WHERE NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1');
