INSERT OR IGNORE INTO guide_spots(guide_id,spot_id,sort_order) SELECT 106,24,2 WHERE NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1') AND EXISTS(SELECT 1 FROM guides WHERE id=106 AND title='南阳两天人文线：把院落、图像与人物分开读');
INSERT OR IGNORE INTO guides(id,city_id,title,subtitle,intro,image,source_url,theme,duration_minutes,sections) SELECT 107,4,'泉州古城半日：一座寺院与两种小吃的取舍','先看开元寺与西街，再决定面线糊、肉粽怎样安排','适合只有半天、既想看建筑又想尝一点地方食味的人。把看塔、街巷与坐下用餐分成三个时段，让小吃帮助休息，而不是制造一条新的赶路清单。','/assets/quanzhou.jpg','https://www.quanzhou.gov.cn/lyb/lswh/zdww/201510/t20151029_183313.htm','街巷生活',240,'[{"title":"半天先选一个核心","body":"这段行程以开元寺为核心，西街与用餐是可以伸缩的部分。先查开放要求、起点与返回方式，再决定到达后先吃还是先参观。不要把洛阳桥也当作附近一小段追加进去；它需要另外的去返安排，会改变这半天原本的步行与休息结构。"},{"title":"寺院先看整体，再看一处细节","body":"先按导览理解寺院空间，认识双塔的位置，再选石构细节或殿宇的一部分细看。镇国塔、仁寿塔不只是合影背景，比较塔身层次能让观察更具体。参观顺序依现场管理，摄影不打扰活动；在寺院已经停留较久时，就相应缩短后面的街巷。"},{"title":"西街只走一段能返回的路线","body":"离寺后选清晰的结束位置，沿途看看铺面、巷口与生活使用，不必找齐所有热门机位。同行想分别逛店时约定集合点和时间；对他人住宅或店内陈设感兴趣也先询问。人流集中或雨势较大时，提前结束街区步行，坐下来用餐也可以成为自然收尾。"},{"title":"面线糊：先问基础份与配料","body":"先看菜单，明确基础份包含什么，再选择少量加料；不同配料可能分别计价。汤底和配料可能涉及不同肉类、海产品与蛋，忌口要在点单前问清。初次尝试不必把所有配料都加齐，用一碗适合自己的份量了解口感，比一边赶路一边端着热汤更舒服。"},{"title":"烧肉粽：先把它算成一份主食","body":"想再尝肉粽时先问大小、馅料和酱料，决定独自吃还是与同伴分食。已经吃过一碗足量面线糊，就把肉粽留到另一餐；小吃的名称不代表食量一定很小。两种都想尝可以减少加料、合理分食，不需要为了清单完整把一顿休息吃成负担。"},{"title":"一个容易收尾的下午","body":"吃完先确认当前到返程接驳点的路线，再离开街巷。把最喜欢的一处建筑细节和一种适合自己的口味记下来，下次再扩展古桥或其他主题。价格、菜单与营业会变，这份组合只提供安排方法，出发前仍需查询实际供应，不预设任何门店当天一定营业。"}]' WHERE NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1');
INSERT OR IGNORE INTO guide_spots(guide_id,spot_id,sort_order) SELECT 107,5,0 WHERE NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1') AND EXISTS(SELECT 1 FROM guides WHERE id=107 AND title='泉州古城半日：一座寺院与两种小吃的取舍');
INSERT OR IGNORE INTO guides(id,city_id,title,subtitle,intro,image,source_url,theme,duration_minutes,sections) SELECT 108,4,'从双塔到石桥：泉州古建观察的四个问题','看位置、看结构、读说明，再把观察写成自己的话','适合不想只拍建筑外观、又没有专业建筑基础的人。以开元寺与洛阳桥为两种尺度，带着可回答的小问题参观，让旅途更容易留下具体记忆。','/assets/quanzhou-bridge.jpg','https://www.quanzhou.gov.cn/lyb/lswh/zdww/201609/t20160913_372301.htm','人文历史',480,'[{"title":"问题一：建筑为什么在这里","body":"在开元寺先看双塔与寺院轴线、院落的相对位置；到洛阳桥则看桥与水面、两岸的关系。先描述现场可见的空间，再读资料补充用途与历史，不急着给每一处安排象征解释。两个场所之间查询完整交通，能否同日完成以去返和体力为前提。"},{"title":"问题二：整体由哪些部分组成","body":"看塔先比较层次、轮廓与前后关系，看桥则区分桥面、桥墩与两端衔接。只在开放位置观察，不为了凑齐照片进入塔内限制空间或桥下非开放岸线。对看不清的部分可以留问题，不用靠想象填满；普通游客能够说清整体与局部，已经完成很好的观察。"},{"title":"问题三：说明补充了什么","body":"选择一块正式说明或展签，看看它提供了哪些单凭外观不能确定的信息，例如名称、建造背景或后来的修缮。把资料中的解释与自己的现场描述分开写，避免把同一地点不同年代的内容合成一个简单标签。遇到传说也保留其叙述身份，不直接作为结构与年代的证据。"},{"title":"问题四：怎样用照片与文字互相说明","body":"每处留一张整体、一张允许拍摄的局部，再写一句两张图怎样相互补充。比如整体说明塔的组合，局部说明石构细节；桥的整体说明跨越关系，局部说明通行空间。照片不是越多越好，能够用自己的话解释一组图，就比照抄热门打卡角度更有意思。"},{"title":"一天的顺序要服从交通","body":"可先在古城完成开元寺参观与午餐，再按核实的去返交通前往洛阳桥；也可根据住处反向安排。无论顺序如何，都为转场单独留时段，不把它算进参观的一小时里。行程紧时只选一处练习完整观察，另一处留到下一次，不为两种建筑都出现而赶场。"},{"title":"雨天与人多时怎样保留主题","body":"人多时减少对固定机位的等待，转向不阻碍通行的观察点；雨大或风强时减少桥面和露天停留，依现场安排结束。回住处后可以根据官方资料整理问题与照片，但不把没有到达的位置写成亲历。主题仍然成立：留下几个看懂的细节，而不是一张完成全部地名的勾选表。"}]' WHERE NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1');
