INSERT OR IGNORE INTO guides(id,city_id,title,subtitle,intro,image,source_url,theme,duration_minutes,sections) SELECT 109,5,'大理三天，不把环湖当作每天的任务','古城、三塔和一段湖岸，另给抵达与天气留半天','适合想慢慢看大理、同时希望计划可执行的人。按片区和体力安排三天，区分大理站、古城与具体湖岸，把多出来的一天用来从容，而不是继续加点。','/assets/dali-town.jpg','https://www.yndali.gov.cn/dlsrmzf/c103380/pc/content/1985989376943951872/content_1985989376943951872.html','山水风景',1440,'[{"title":"先把行李与住宿放进地图","body":"确认大理站、下关城区、古城和想去湖岸的位置，订住处时比较实际接驳，而不只看“近洱海”的描述。带行李抵达当天先解决入住或寄放，再决定开始哪一小段步行。临时换住处会增加收拾、取放与交通时间，三天短行不必为了不同照片每天搬一次。"},{"title":"第一天：古城只走几条街","body":"抵达较早时留半天看古城，先熟悉方向，再选两三条允许通行的街巷。观察建筑与沿街日常，找合适的地方坐下用餐；乳扇可少量尝试，不必把一整张小吃名单搬进这一餐。抵达较晚则缩成住处附近的一段，先休息，给第二天保留精力。"},{"title":"第二天：三塔与古城按实际接驳组合","body":"三塔参观先看整体组合，再比较主塔与小塔的轮廓和细节，按现场导览安排园区内步行。与古城距离关系仍需查实际交通与入口，不能只按地图上的相邻估时。午间留下完整休息，剩余半天可回看喜欢的街巷，也可直接休息，不要求继续转到湖岸。"},{"title":"第三天：湖岸只选一个明确片区","body":"选具体到达点，去程与回程一起查；在开放步道留一段拍照、观察和休息时间。湖景不需要用绕一整圈来证明看过，遇到喜欢的位置多停一会儿，也可以结束当天重点。若第三天就是返程日，应把湖岸提前到更从容的一天，最后半天只留方便收尾的活动。"},{"title":"天气可以改变两天的顺序","body":"湖岸停留比较依赖当天风雨，可根据预报调整顺序；三塔与古城也有户外步行，不应被写成无条件的雨天替代。天气不合适时减少路线，而不是加速去另一个片区追光。把半天空白用来等待、休息或吃一顿饭，实际开放与活动范围始终按现场安排。"},{"title":"把食味与距离一起考虑","body":"乳扇适合少量体验，问清做法与酱料；巍山耙肉饵丝则提醒我们，大理州的风味并不都在古城旁。已经有三塔与湖岸安排，就优先查询顺路餐食；想专程去巍山需另留完整行程。记录真正吃到的口味与花费，不用把没去的地方写进自己的旅行经历。"}]' WHERE NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1');
