INSERT OR IGNORE INTO guide_spots(guide_id,spot_id,sort_order) SELECT 109,6,2 WHERE NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1') AND EXISTS(SELECT 1 FROM guides WHERE id=109 AND title='大理三天，不把环湖当作每天的任务');
INSERT OR IGNORE INTO guides(id,city_id,title,subtitle,intro,image,source_url,theme,duration_minutes,sections) SELECT 110,5,'洱海湖岸半日：给风景留一段真正的停留','先选一段开放湖岸，再把拍照、步行和返程放在一起','适合不想环湖赶点、希望拍照也能休息的人。用一个明确去处替代一串远距离地名，不依赖固定日落，让半天的湖岸安排随天气自然收放。','/assets/dali.jpg','https://www.yndali.gov.cn/dlsrmzf/c103380/pc/content/1985989376943951872/content_1985989376943951872.html','山水风景',240,'[{"title":"先把“去洱海”改成具体目的地","body":"确定具体湖岸片区、允许步行的位置与返回方式，再查住处到这里的去程。地图上的“洱海”是湖泊名称，不是唯一的下车点；相片里看起来相近的岸边，实际可能需要不同的接驳。时间有限就只选一处，避免到了第一处又临时赶往另一侧。"},{"title":"前半段先走，不急着拍","body":"抵达后先确认能走的范围和回程集合位置，沿正常步道慢走一段，看看远处山体、水面与岸边空间。等自己知道最想看什么再取景，不用一下车就连续拍照。同行有人走累时，选择允许停留的位置休息，把坐下来观察也算作这一段旅行的内容。"},{"title":"中间留一段不移动的时间","body":"在同一位置停留20～30分钟，是一种可以尝试的观察练习，而非必须完成的任务。比较风、水面、树影与人流的变化，试着拍一张远景和一张近处细节。光线不理想时也可以只看不拍；若现场不适合久留，就缩短停留，保持通道畅通。"},{"title":"拍照范围以开放步道为边界","body":"不为了接近水面进入湿地、田地、私人区域或其他限制位置，也不把越过护栏当作获得好照片的办法。出现清晰人物时先尊重对方意愿，同行合影选不阻挡通行的位置。照片能表达当天真实的风景就足够，不需要复制网络中不明拍摄条件的角度。"},{"title":"骑行与其他活动需要另作判断","body":"如果想骑行，先核对允许路段、取还车、体力与去返条件，不在抵达后仅凭路边有车就马上改变计划。步行、骑行与车辆接驳是不同安排，不能直接套用同一段耗时。天气变化时及时缩短户外活动，留足返回住处或接上下一段交通的余量。"},{"title":"结束点和一顿饭让半天闭合","body":"返回前先确认交通，从约定位置结束步行；餐食尽量选在返程方向，不再为一道小吃跨片区。日落与倒影都受天气影响，不把它们当作这半天必须交出的成果。能在一段湖岸里走过、停过、观察过，再从容返回，就已经完成一次有内容的湖边旅行。"}]' WHERE NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1');
INSERT OR IGNORE INTO guide_spots(guide_id,spot_id,sort_order) SELECT 110,6,0 WHERE NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name='editorial-content-20261026-v1') AND EXISTS(SELECT 1 FROM guides WHERE id=110 AND title='洱海湖岸半日：给风景留一段真正的停留');
INSERT OR IGNORE INTO schema_migrations(name) VALUES('editorial-content-20261026-v1');
COMMIT;
